    def test_freertos_semaphore_take_upstream_pair_is_source_closed(self) -> None:
        helper_name = (
            "open_cfw_freertos_queue_get_disinherit_priority_after_timeout"
        )
        take_name = (
            "open_cfw_freertos_queue_semaphore_take_upstream_candidate"
        )
        reports = {
            item["extraction"]["function"]: item
            for item in self.component_report["relocated_leaves"]
            if item["extraction"]["function"] in (helper_name, take_name)
        }
        self.assertEqual(set(reports), {helper_name, take_name})
        helper = reports[helper_name]
        take = reports[take_name]
        self.assertEqual(
            helper["source"],
            {
                "path": (
                    "components/shared/freertos/"
                    "runtime_freertos_queue_get_disinherit_priority_"
                    "after_timeout.c"
                ),
                "size": 2620,
                "sha256": (
                    "37a4ea5a258befb3b607bf5b0c3e6f28"
                    "b60ed11279b98e13910e0a125519db3a"
                ),
                "license": "MIT",
                "origin": helper["source"]["origin"],
                "upstream": helper["source"]["upstream"],
                "upstream_commit": "def7d2df2b0506d3d249334974f51e427c17a41c",
                "evidence": (
                    "docs/research/freertos-queue-disinherit-priority-"
                    "after-timeout-candidate-audit.md"
                ),
            },
        )
        self.assertEqual(
            take["source"]["sha256"],
            "7bc1adb794188c36fe0693ef4dcf0e45"
            "b83cb32ba523142ecb72e703d65979e2",
        )
        self.assertEqual(helper["placement"]["offset"], 120696)
        self.assertEqual(helper["placement"]["size"], 18)
        self.assertEqual(take["placement"]["offset"], 120716)
        self.assertEqual(take["placement"]["size"], 602)
        self.assertEqual(helper["extraction"]["relocations"], [])
        self.assertEqual(
            take["extraction"]["relocations"],
            [{
                "offset": 580,
                "runtime_address": 0x007B1CF4,
                "runtime_address_hex": "0x007B1CF4",
                "symbol": helper_name,
                "symbol_type": "STT_NOTYPE",
                "target_address": 0x007B1A9C,
                "target_address_hex": "0x007B1A9C",
                "target_function": helper_name,
                "type": "R_ARM_THM_CALL",
                "type_id": 10,
            }],
        )

        overlay_report = self.component_report["overlay"]
        patch = next(
            item for item in overlay_report["patched_sites"]
            if item["name"] == "replace_freertos_queue_semaphore_take"
        )
        self.assertEqual(patch["target_function"], take_name)
        replacement = bytes.fromhex(patch["replacement_hex"])
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                0x00441C44,
                replacement[:4],
                link=False,
            ),
            0x007B1AB0,
        )
        self.assertEqual(replacement[4:], b"\x00\xBF" * 175)

        component = (
            OPENCFW_ROOT / self.component_report["component"]["artifact"]
        ).read_bytes()
        application_base = 0x00438000
        application = component[32:]
        helper_start = 0x00441EC4
        helper_end = 0x00441ED8
        self.assertEqual(
            application[
                helper_start - application_base:
                helper_end - application_base
            ].hex(),
            "416a002904d0006b0068d0f1380000e000207047",
        )

        direct = []
        for offset in range(0, len(application) - 3, 2):
            address = application_base + offset
            encoded = application[offset:offset + 4]
            for link in (True, False):
                try:
                    target = apollo_overlay.decode_thumb_branch(
                        address,
                        encoded,
                        link=link,
                    )
                except apollo_overlay.BuildError:
                    continue
                if (
                    helper_start <= target < helper_end
                    and not helper_start <= address < helper_end
                ):
                    direct.append((address, target, link))
            first, second = struct.unpack_from("<HH", encoded)
            if (
                first & 0xF800 == 0xF000
                and second & 0xD000 == 0x8000
                and ((first >> 6) & 0x0F) < 0x0E
            ):
                sign = (first >> 10) & 1
                immediate = (
                    (sign << 20)
                    | (((second >> 11) & 1) << 19)
                    | (((second >> 13) & 1) << 18)
                    | ((first & 0x003F) << 12)
                    | ((second & 0x07FF) << 1)
                )
                if sign:
                    immediate -= 1 << 21
                target = (address + 4 + immediate) & 0xFFFF_FFFF
                if (
                    helper_start <= target < helper_end
                    and not helper_start <= address < helper_end
                ):
                    direct.append((address, target, "conditional"))
        self.assertEqual(direct, [])

        narrow = []
        for offset in range(0, len(application) - 1, 2):
            address = application_base + offset
            instruction = struct.unpack_from("<H", application, offset)[0]
            targets = []
            if instruction & 0xF800 == 0xE000:
                immediate = instruction & 0x07FF
                if immediate & 0x0400:
                    immediate -= 0x0800
                targets.append(address + 4 + immediate * 2)
            elif (
                instruction & 0xF000 == 0xD000
                and ((instruction >> 8) & 0x0F) < 0x0E
            ):
                immediate = instruction & 0x00FF
                if immediate & 0x0080:
                    immediate -= 0x0100
                targets.append(address + 4 + immediate * 2)
            elif instruction & 0xF500 == 0xB100:
                immediate = (
                    (((instruction >> 9) & 1) << 5)
                    | ((instruction >> 3) & 0x1F)
                )
                targets.append(address + 4 + immediate * 2)
            for target in targets:
                if (
                    helper_start <= target < helper_end
                    and not helper_start <= address < helper_end
                ):
                    narrow.append((address, target))
        self.assertEqual(narrow, [])

        stored = []
        for offset in range(0, len(application) - 3):
            value = struct.unpack_from("<I", application, offset)[0]
            if helper_start <= (value & ~1) < helper_end:
                stored.append((application_base + offset, value))
        self.assertEqual(stored, [])

        recursive = overlay_report["functions"][
            "open_cfw_freertos_queue_take_mutex_recursive"
        ]
        overlay = (
            OPENCFW_ROOT / overlay_report["artifact"]
        ).read_bytes()
        recursive_bytes = overlay[
            recursive["offset"]:
            recursive["offset"] + recursive["size"]
        ]
        recursive_calls = []
        for offset in range(0, recursive["size"] - 13, 2):
            low_first, low_second = struct.unpack_from(
                "<HH", recursive_bytes, offset
            )
            high_first, high_second = struct.unpack_from(
                "<HH", recursive_bytes, offset + 4
            )
            if (
                low_first & 0xFBF0 != 0xF240
                or high_first & 0xFBF0 != 0xF2C0
            ):
                continue
            low_register = (low_second >> 8) & 0x0F
            high_register = (high_second >> 8) & 0x0F
            if low_register != high_register:
                continue
            low = apollo_overlay.thumb_movwt_immediate(
                low_first, low_second
            )
            high = apollo_overlay.thumb_movwt_immediate(
                high_first, high_second
            )
            target = (high << 16) | low
            intervening = struct.unpack_from(
                "<HH", recursive_bytes, offset + 8
            )
            blx = struct.unpack_from("<H", recursive_bytes, offset + 12)[0]
            if (
                target == 0x00441C45
                and intervening == (0x4620, 0x4629)
                and blx == 0x4780 | (low_register << 3)
            ):
                recursive_calls.append(
                    (
                        overlay_report["overlay_runtime_address"]
                        + recursive["offset"] + offset,
                        low_register,
                        target,
                    )
                )
        self.assertEqual(
            recursive_calls,
            [(0x007AE3D4, 2, 0x00441C45)],
        )

    def test_freertos_reset_and_unordered_removal_are_source_closed(self) -> None:
        expected = {
            "open_cfw_freertos_queue_generic_reset": {
                "path": (
                    "components/shared/freertos/"
                    "runtime_freertos_queue_generic_reset.c"
                ),
                "source_size": 4002,
                "source_sha256": (
                    "223758f605ee22220e5a534db4675545c"
                    "c43a1f1fc5f24051c3c7c3cc92d556c"
                ),
                "offset": 121320,
                "size": 172,
                "sha256": (
                    "689da8cc4cd4757e609cdf77b3675ff73"
                    "30fb46ea9b1efc29f4d96772f066baa"
                ),
                "patch": "replace_freertos_queue_generic_reset",
                "stock": (0x00441516, 180),
                "target": 0x007B1D0C,
            },
            "open_cfw_freertos_task_remove_from_unordered_event_list": {
                "path": (
                    "components/shared/freertos/"
                    "runtime_freertos_task_remove_from_unordered_event_list.c"
                ),
                "source_size": 4452,
                "source_sha256": (
                    "3656a2e24d63a2dd92743fde085be59f"
                    "f4c830afb357535b38dbd4a4dc39f77c"
                ),
                "offset": 121492,
                "size": 214,
                "sha256": (
                    "c4a89f560a07598f3af72a4ca0e3a6b"
                    "da1f23bd86e6f777ecea690f6db67ecdd"
                ),
                "patch": (
                    "replace_freertos_task_remove_from_unordered_event_list"
                ),
                "stock": (0x0045547C, 218),
                "target": 0x007B1DB8,
            },
        }
        selected = [
            item for item in self.component_report["relocated_leaves"]
            if item["extraction"]["function"] in expected
        ]
        self.assertEqual(len(selected), 2)
        self.assertEqual(
            {item["extraction"]["function"] for item in selected},
            set(expected),
        )
        patches = [
            item for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] in {value["patch"] for value in expected.values()}
        ]
        self.assertEqual(len(patches), 2)
        patches_by_name = {item["name"]: item for item in patches}

        component = (
            OPENCFW_ROOT / self.component_report["component"]["artifact"]
        ).read_bytes()
        application = component[32:]
        for report in selected:
            name = report["extraction"]["function"]
            pins = expected[name]
            with self.subTest(function=name):
                self.assertEqual(report["source"]["path"], pins["path"])
                self.assertEqual(report["source"]["size"], pins["source_size"])
                self.assertEqual(
                    report["source"]["sha256"], pins["source_sha256"]
                )
                self.assertEqual(report["source"]["license"], "MIT")
                self.assertEqual(
                    report["source"]["upstream_commit"],
                    "def7d2df2b0506d3d249334974f51e427c17a41c",
                )
                self.assertEqual(report["placement"]["offset"], pins["offset"])
                self.assertEqual(report["placement"]["size"], pins["size"])
                self.assertEqual(report["pins"]["sha256"], pins["sha256"])
                self.assertEqual(report["extraction"]["relocations"], [])

                patch = patches_by_name[pins["patch"]]
                self.assertEqual(patch["target_function"], name)
                self.assertEqual(patch["branch"], "b_w")
                replacement = bytes.fromhex(patch["replacement_hex"])
                stock_address, stock_size = pins["stock"]
                self.assertEqual(len(replacement), stock_size)
                self.assertEqual(
                    apollo_overlay.decode_thumb_branch(
                        stock_address,
                        replacement[:4],
                        link=False,
                    ),
                    pins["target"],
                )
                self.assertEqual(
                    replacement[4:], b"\x00\xBF" * ((stock_size - 4) // 2)
                )
                offset = stock_address - 0x00438000
                self.assertEqual(
                    application[offset:offset + stock_size], replacement
                )

