        overlay_report = self.component_report["overlay"]
        patch_sites = {
            site["name"]: site
            for site in overlay_report["patched_sites"]
        }
        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        overlay = (
            OPENCFW_ROOT / overlay_report["artifact"]
        ).read_bytes()

        for patch_name, pins in expected.items():
            with self.subTest(patch=patch_name):
                site = patch_sites[patch_name]
                expected_address, expected_size, stock_sha, function = (
                    pins["site"]
                )
                self.assertEqual(
                    (
                        site["runtime_address"],
                        site["expected_size"],
                        site["expected_sha256"],
                        site["target_function"],
                    ),
                    pins["site"],
                )
                stock = base[
                    site["payload_offset"]:
                    site["payload_offset"] + expected_size
                ]
                self.assertEqual(len(stock), expected_size)
                self.assertEqual(
                    hashlib.sha256(stock).hexdigest(),
                    stock_sha,
                )

                offset, size, body_sha = pins["body"]
                self.assertEqual(
                    overlay_report["functions"][function],
                    {"offset": offset, "size": size},
                )
                compiled = overlay[offset:offset + size]
                self.assertEqual(len(compiled), size)
                self.assertEqual(
                    hashlib.sha256(compiled).hexdigest(),
                    body_sha,
                )
                self.assertEqual(
                    site["target_address"],
                    overlay_report["overlay_runtime_address"] + offset,
                )
                self.assertEqual(site["branch"], "b_w")

        expected_wrapper_relocations = {
            "open_cfw_freertos_queue_create_mutex_static": [
                (
                    22,
                    "open_cfw_freertos_queue_generic_create_static",
                    10,
                ),
                (
                    28,
                    "open_cfw_freertos_queue_initialise_mutex",
                    10,
                ),
            ],
            "open_cfw_freertos_queue_create_counting_semaphore_static": [
                (
                    28,
                    "open_cfw_freertos_queue_generic_create_static",
                    10,
                ),
            ],
            "open_cfw_freertos_queue_create_counting_semaphore": [
                (
                    14,
                    "open_cfw_freertos_queue_generic_create",
                    10,
                ),
            ],
        }
        for function_name, expected_relocations in (
            expected_wrapper_relocations.items()
        ):
            function = overlay_report["functions"][function_name]
            observed = [
                (
                    relocation["site"] - function["offset"],
                    relocation["symbol"],
                    relocation["type"],
                )
                for relocation in overlay_report["link"][
                    "resolved_relocations"
                ]
                if (
                    function["offset"]
                    <= relocation["site"]
                    < function["offset"] + function["size"]
                )
            ]
            self.assertEqual(observed, expected_relocations)

        assertion_call = bytes.fromhex("4af2a500c0f25f008047")
        mutex_function = overlay_report["functions"][
            "open_cfw_freertos_queue_create_mutex_static"
        ]
        mutex_body = overlay[
            mutex_function["offset"]:
            mutex_function["offset"] + mutex_function["size"]
        ]
        self.assertNotIn(assertion_call, mutex_body)
        for function_name in (
            "open_cfw_freertos_queue_create_counting_semaphore_static",
            "open_cfw_freertos_queue_create_counting_semaphore",
        ):
            function = overlay_report["functions"][function_name]
            body = overlay[
                function["offset"]:function["offset"] + function["size"]
            ]
            self.assertIn(assertion_call, body)

