    def test_littlefs_file_rewind_private_production_contract_is_exact(
        self,
    ) -> None:
        function_name = "open_cfw_littlefs_file_rewind_private"
        seam_name = "open_cfw_littlefs_file_seek_private"
        source_path = COMPONENT_ROOT / "runtime_littlefs_file_rewind_private.c"
        header_path = source_path.with_suffix(".h")
        pinned_files = {
            source_path: (
                1239,
                "e6afb5b67671b3219971b19c20290c6"
                "01568752d814064147f5ccd4118f5acc8",
            ),
            header_path: (
                1743,
                "7430dcd1ad1ea3973d619f2d67d8d8b1"
                "1a688018d48a3bc26a40e407d1fedb56",
            ),
        }
        self.assertEqual(
            {
                path.name: (
                    path.stat().st_size,
                    hashlib.sha256(path.read_bytes()).hexdigest(),
                )
                for path in pinned_files
            },
            {path.name: pin for path, pin in pinned_files.items()},
        )

        config = apollo_overlay.load_config(COMPONENT_ROOT / "overlay.json")
        self.assertEqual(
            (
                len(config["functions"]),
                len(config["patch_sites"]),
                len(config["relocated_leaves"]),
            ),
            (1049, 987, 480),
        )
        self.assertEqual(
            config["expected"],
            {
                "overlay_size": 174816,
                "overlay_sha256": (
                    "b732d58cda6cf0a05c15e3eeb5beaa6bcf472a2822065ae6ca614a3417f7f6bf"
                ),
                "component_size": 3698212,
                "component_sha256": (
                    "125cfeb1bda76cbb2cc7d7d1e6fab92e00c63c4f00f5fa8a893c6f33912a55f3"
                ),
            },
        )
        self.assertEqual(
            config["toolchain_profiles"]["linux-clang"]["expected"],
            {
                "overlay_size": 145208,
                "overlay_sha256": (
                    "fac5b48b6ae2eac985a0a65ddb8d1595d"
                    "d10e2abcbdd0c6a3bb562f72e43a826"
                ),
                "component_size": 3668604,
                "component_sha256": (
                    "378c868e151060a59ab91b0de1a722e8"
                    "678b8e1da8eede248c5702ccf8902798"
                ),
            },
        )
        self.assertEqual(config["functions"].count(function_name), 1)
        leaves = [
            leaf
            for leaf in config["relocated_leaves"]
            if leaf["function"] == function_name
        ]
        self.assertEqual(len(leaves), 1)
        leaf = leaves[0]
        self.assertEqual(
            leaf["source"],
            {
                "path": source_path.relative_to(OPENCFW_ROOT).as_posix(),
                "size": 1239,
                "sha256": pinned_files[source_path][1],
                "license": "BSD-3-Clause",
                "origin": (
                    "bounded freestanding adaptation of authenticated "
                    "littlefs v2.10.1 lfs_file_rewind_ with a retained "
                    "private lfs_file_seek_ provider seam"
                ),
                "upstream": (
                    "https://github.com/littlefs-project/littlefs/blob/"
                    "0494ce7169f06a734a7bd7585f49a9fa91fa7318/lfs.c"
                ),
                "upstream_commit": (
                    "0494ce7169f06a734a7bd7585f49a9fa91fa7318"
                ),
                "evidence": (
                    "docs/research/littlefs-file-rewind-source-audit.md"
                ),
            },
        )
        relocation = {
            "offset": 6,
            "type": "R_ARM_THM_CALL",
            "symbol": seam_name,
            "symbol_type": "STT_NOTYPE",
            "target_address": 0x004CE3BC,
        }
        apple_expected = {
            "size": 16,
            "sha256": (
                "1c2e2b1fded0de515345b90fe34de51a"
                "9c0f08a02a5ad983c1120481c51c5783"
            ),
            "alignment": 4,
            "offset": 124480,
            "unrelocated_sha256": (
                "46e8bab056ad39ced45edb5da2612f64"
                "70674ab5a428df7f08822f6c2d9e184b"
            ),
        }
        linux_expected = {
            "size": 16,
            "sha256": (
                "9731cbf3ff15be31186591ed148d009ae"
                "8985cb18bdfca3ba365aeb0897e3fd1"
            ),
            "alignment": 4,
            "offset": 126300,
            "unrelocated_sha256": apple_expected["unrelocated_sha256"],
        }
        self.assertTrue(leaf["strict_relocation_contract"])
        self.assertEqual(leaf["expected"], apple_expected)
        self.assertEqual(leaf["relocations"], [relocation])
        self.assertEqual(
            leaf["toolchain_profiles"]["linux-clang"],
            {
                "reviewed_version_prefix": "Homebrew clang version 22.1.8",
                "expected": linux_expected,
                "relocations": [relocation],
            },
        )
        self.assertEqual(0x00794324 + apple_expected["offset"], 0x007B2964)
        self.assertEqual(0x00794324 + linux_expected["offset"], 0x007B3080)
        self.assertEqual(
            [
                patch
                for patch in config["patch_sites"]
                if patch.get("target_function") == function_name
            ],
            [{
                "name": "replace_littlefs_file_rewind_private",
                "runtime_address": 0x004CE460,
                "expected_size": 18,
                "expected_sha256": (
                    "be02691b2e7339d7dd1d54b31712c3e8"
                    "563e5a86f4406a469888640fad9435cd"
                ),
                "branch": "b_w",
                "target_function": function_name,
            }],
        )

        extracted = next(
            item
            for item in self.component_report["relocated_leaves"]
            if item["extraction"]["function"] == function_name
        )
        self.assertEqual(
            extracted["placement"],
            {
                "offset": 124480,
                "runtime_address": 0x007B2964,
                "runtime_address_hex": "0x007B2964",
                "size": 16,
                "alignment": 4,
                "padding_before": 0,
            },
        )
        self.assertEqual(
            (
                extracted["extraction"]["sha256"],
                extracted["extraction"]["unrelocated_sha256"],
                extracted["extraction"]["relocation_count"],
            ),
            (
                apple_expected["sha256"],
                apple_expected["unrelocated_sha256"],
                1,
            ),
        )
        self.assertEqual(
            {
                key: extracted["extraction"]["relocations"][0][key]
                for key in (
                    "offset",
                    "type",
                    "symbol",
                    "symbol_type",
                    "target_address",
                )
            },
            relocation,
        )
        patch = next(
            item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] == "replace_littlefs_file_rewind_private"
        )
        replacement = bytes.fromhex(patch["replacement_hex"])
        self.assertEqual(
            (replacement.hex(), hashlib.sha256(replacement).hexdigest()),
            (
                "e4f280ba" + "00bf" * 7,
                "d6d0947d5f648f4acdab371be5d051e3"
                "c89ad1f2e44b88da2ce0600e7b2f3751",
            ),
        )

    def test_only_declared_spans_wrapper_and_overlay_differ(self) -> None:
        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        component = bytearray(
            (
                OPENCFW_ROOT
                / self.component_report["component"]["artifact"]
            ).read_bytes()
        )
        overlay = (
            OPENCFW_ROOT / self.component_report["overlay"]["artifact"]
        ).read_bytes()

        self.assertEqual(bytes(component[len(base):]), overlay)
        component[:32] = base[:32]
        for site in self.component_report["overlay"]["patched_sites"]:
            offset = site["payload_offset"]
            length = (
                len(bytes.fromhex(site["expected_hex"]))
                if "expected_hex" in site
                else site["expected_size"]
            )
            component[offset:offset + length] = base[offset:offset + length]
        self.assertEqual(bytes(component[:len(base)]), base)

