    def test_duration_delay_family_is_exact_and_uses_in_place_entry(
        self,
    ) -> None:
        copies = {
            site["name"]: site
            for site in self.component_report["overlay"]["patched_sites"]
            if site["branch"] == "copy"
        }
        self.assertEqual(
            set(copies),
            {
                "replace_duration_delay",
                "replace_format_span",
                "replace_duration_delay_ms_wrapper",
                "replace_duration_delay_us_wrapper",
                "replace_duration_delay_cycle_load_image",
                "replace_ble_msgtx_application_initialize",
                "replace_ble_msgtx_thread_initialize",
                "replace_file_system_sync",
                "replace_runtime_noop_output",
                "replace_freertos_ul_set_interrupt_mask",
                "replace_freertos_v_clear_interrupt_mask",
            },
        )
        site = copies["replace_duration_delay"]
        self.assertEqual(site["runtime_address"], 0x004807A0)
        self.assertEqual(site["expected_size"], 92)
        self.assertEqual(
            site["expected_sha256"],
            "10ca20e1a01a30d82ec2e215caaa2abe57087c1e68ff4182e4e848d974326a6f",
        )

        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        overlay = (
            OPENCFW_ROOT
            / self.component_report["overlay"]["artifact"]
        ).read_bytes()
        function = self.component_report["overlay"]["functions"][
            "open_cfw_delay_us"
        ]
        compiled = overlay[
            function["offset"]:function["offset"] + function["size"]
        ]
        stock = base[
            site["payload_offset"]:site["payload_offset"] + site["expected_size"]
        ]
        self.assertEqual(compiled, stock)
        self.assertEqual(bytes.fromhex(site["replacement_hex"]), stock)
        self.assertEqual(
            hashlib.sha256(compiled).hexdigest(),
            site["expected_sha256"],
        )
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                0x004807EA,
                compiled[0x4A:0x4E],
                link=True,
            ),
            0x00000040,
        )

        for name, address, size, digest, function_name, call_site in (
            (
                "replace_duration_delay_ms_wrapper",
                0x004910F4,
                14,
                "566ba14b421d07c4b79a1aba6d3cf0e75b0ce4ad752150e6690288bddf79f59f",
                "open_cfw_delay_ms",
                0x004910FC,
            ),
            (
                "replace_duration_delay_us_wrapper",
                0x00491102,
                8,
                "5d53c0f861f1e995a334442c81f3f3f1f5df6dac4f8685c61ffadf12303c79fc",
                "open_cfw_delay_us_passthrough",
                0x00491104,
            ),
        ):
            wrapper_site = copies[name]
            self.assertEqual(wrapper_site["runtime_address"], address)
            self.assertEqual(wrapper_site["expected_size"], size)
            self.assertEqual(wrapper_site["expected_sha256"], digest)
            wrapper_function = self.component_report["overlay"]["functions"][
                function_name
            ]
            compiled_wrapper = overlay[
                wrapper_function["offset"]:
                wrapper_function["offset"] + wrapper_function["size"]
            ]
            stock_wrapper = base[
                wrapper_site["payload_offset"]:
                wrapper_site["payload_offset"] + size
            ]
            self.assertEqual(compiled_wrapper, stock_wrapper)
            self.assertEqual(
                bytes.fromhex(wrapper_site["replacement_hex"]),
                stock_wrapper,
            )
            branch_offset = call_site - address
            self.assertEqual(
                apollo_overlay.decode_thumb_branch(
                    call_site,
                    compiled_wrapper[branch_offset:branch_offset + 4],
                    link=True,
                ),
                0x004807A0,
            )

        cycle_site = copies["replace_duration_delay_cycle_load_image"]
        self.assertEqual(cycle_site["runtime_address"], 0x00794310)
        self.assertEqual(cycle_site["expected_size"], 6)
        self.assertEqual(
            cycle_site["expected_sha256"],
            "c5c855e6f7cfc08b58f586a46b44b895bc33bda66242061d73357d9f93e76471",
        )
        cycle_function = self.component_report["overlay"]["functions"][
            "open_cfw_delay_cycles"
        ]
        compiled_cycle = overlay[
            cycle_function["offset"]:
            cycle_function["offset"] + cycle_function["size"]
        ]
        application_offset = 32 + 0x00794310 - 0x00438000
        stock_cycle = base[application_offset:application_offset + 6]
        self.assertEqual(
            compiled_cycle,
            bytes.fromhex("0138fdd17047"),
        )
        self.assertEqual(compiled_cycle, stock_cycle)
        self.assertEqual(
            bytes.fromhex(cycle_site["replacement_hex"]),
            stock_cycle,
        )
        self.assertEqual(
            cycle_site["scatter_literal"],
            {
                "record_address": 0x0075D3E0,
                "record_address_hex": "0x0075D3E0",
                "handler_address": 0x0043A11E,
                "handler_address_hex": "0x0043A11E",
                "stream_address": 0x0079430E,
                "stream_address_hex": "0x0079430E",
                "stream_size": 22,
                "literal_data_offset": 2,
                "literal_length": 14,
                "destination_address": 0x00000040,
                "destination_address_hex": "0x00000040",
                "runtime_address": 0x00000040,
                "runtime_address_hex": "0x00000040",
            },
        )
        self.assertFalse(
            [
                relocation
                for relocation in self.component_report["overlay"]["link"][
                    "resolved_relocations"
                ]
                if (
                    relocation["symbol"] == "open_cfw_delay_us"
                    and function["offset"]
                    <= relocation["site"]
                    < function["offset"] + function["size"]
                )
            ]
        )

        for function_name, fixed_parts in (
            (
                "open_cfw_ui_display_operation_zero",
                (bytes.fromhex("40f2a177"), bytes.fromhex("c0f24807")),
            ),
            (
                "open_cfw_ui_display_operation_one",
                (bytes.fromhex("40f2a177"), bytes.fromhex("c0f24807")),
            ),
            (
                "open_cfw_ui_display_irq_bit6",
                (bytes.fromhex("40f2a171"), bytes.fromhex("c0f24801")),
            ),
        ):
            caller = self.component_report["overlay"]["functions"][
                function_name
            ]
            caller_bytes = overlay[
                caller["offset"]:caller["offset"] + caller["size"]
            ]
            for fixed_part in fixed_parts:
                self.assertIn(fixed_part, caller_bytes)

    def test_duration_cycle_load_image_rejects_scatter_drift(self) -> None:
        config = apollo_overlay.load_config(COMPONENT_ROOT / "overlay.json")
        config = json.loads(json.dumps(config))
        site = next(
            item
            for item in config["patch_sites"]
            if item["name"] == "replace_duration_delay_cycle_load_image"
        )
        site["scatter_literal"]["destination_address"] = 0x44
        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        overlay = (
            OPENCFW_ROOT
            / self.component_report["overlay"]["artifact"]
        ).read_bytes()
        with self.assertRaisesRegex(
            apollo_overlay.BuildError,
            "scatter destination",
        ):
            apollo_overlay.patch_component(
                base=base,
                overlay=overlay,
                functions=self.component_report["overlay"]["functions"],
                config=config,
            )

    def test_duration_delay_source_executes_against_host_oracles(self) -> None:
        fixture = (
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "duration_delay_host.c"
        )
        with tempfile.TemporaryDirectory() as directory:
            temporary = Path(directory)
            library = temporary / (
                "duration_delay.dylib"
                if sys.platform == "darwin"
                else "duration_delay.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))

            delay = loaded.open_cfw_delay_us
            delay.argtypes = [ctypes.c_uint]
            delay.restype = None
            delay_ms = loaded.open_cfw_delay_ms
            delay_ms.argtypes = [ctypes.c_uint]
            delay_ms.restype = None
            delay_passthrough = loaded.open_cfw_delay_us_passthrough
            delay_passthrough.argtypes = [ctypes.c_uint]
            delay_passthrough.restype = None
            reset = loaded.open_cfw_test_duration_delay_reset
            reset.argtypes = []
            reset.restype = None

            def word(name: str) -> ctypes.c_uint:
                return ctypes.c_uint.in_dll(loaded, name)

            cases = (
                (1, 0, 0, 0),
                (1, 1, 1, 17),
                (0, 1000, 1, 31985),
                (3, 1000001, 1, 32000017),
                (2, 0, 0, 0),
                (2, 1, 1, 59),
                (2, 1000, 1, 83309),
                (2, 1000001, 1, 83333392),
            )
            for perf_status, usec, calls, cycles in cases:
                with self.subTest(
                    perf_status=perf_status,
                    usec=usec,
                ):
                    reset()
                    word(
                        "open_cfw_test_duration_delay_perf_status"
                    ).value = perf_status
                    delay(usec)
                    self.assertEqual(
                        word(
                            "open_cfw_test_duration_delay_cycle_calls"
                        ).value,
                        calls,
                    )
                    self.assertEqual(
                        word(
                            "open_cfw_test_duration_delay_cycles"
                        ).value,
                        cycles,
                    )

            reset()
            delay_ms(1)
            self.assertEqual(
                word("open_cfw_test_duration_delay_cycle_calls").value,
                1,
            )
            self.assertEqual(
                word("open_cfw_test_duration_delay_cycles").value,
                31985,
            )

            reset()
            delay_passthrough(1)
            self.assertEqual(
                word("open_cfw_test_duration_delay_cycle_calls").value,
                1,
            )
            self.assertEqual(
                word("open_cfw_test_duration_delay_cycles").value,
                17,
            )

