        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        run_base = 0x00438000

        def direct_callers(target: int) -> list[int]:
            callers = []
            application = base[32:]
            for offset in range(0, len(application) - 3, 2):
                address = run_base + offset
                try:
                    decoded = apollo_overlay.decode_thumb_branch(
                        address,
                        application[offset:offset + 4],
                        link=True,
                    )
                except apollo_overlay.BuildError:
                    continue
                if decoded == target:
                    callers.append(address)
            return callers

        self.assertEqual(direct_callers(0x00490C84), [0x00490D02])
