            value = struct.unpack_from("<I", application, offset)[0]
            for entry, size in ranges.items():
                if value == (entry | 1):
                    entry_words[entry].append(address)
                if value & 1 and entry < (value & ~1) < entry + size:
                    interior_targets.append(("pointer", address, value))
