    def test_event_loop_cluster_executes_against_host_oracles(
        self,
    ) -> None:
        expected_sites = {
            "replace_event_loop_initialize": (
                0x004764E0,
                414,
                "d5c8eee2a3aa006b6cacb9ecdf509aae6a4e3552bc0eb26e208ec64bd0dc3c71",
            ),
            "replace_event_loop_task": (
                0x00476680,
                108,
                "cd18e9f3b84c8ee5f394202e1831b093856cfa4df675c44c4a5c92983ac95d76",
            ),
            "replace_event_loop_push": (
                0x004766EC,
                188,
                "13fca29403f4d51ebce4643fda4b92976832612cad8cef65f1faea4970f984be",
            ),
            "replace_event_loop_timer_callback": (
                0x004767A8,
                470,
                "5240df073fc2190b345796c52e1cb58c513984bb877e48cac02c1d238dca764b",
            ),
            "replace_event_loop_push_delayed": (
                0x0047697E,
                336,
                "496f1779e410338cac437436bd548d4e38f48a23764f7134f6a1100e5da81048",
            ),
            "replace_event_loop_remove_delayed": (
                0x00476ACE,
                290,
                "6491c4dabd2c4ad8867e7f32e46439da9a1f321dfde163a6d5f710b1a29667ec",
            ),
        }
        sites = {
            item["name"]: item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] in expected_sites
        }
        self.assertEqual(set(sites), set(expected_sites))
        for name, expected in expected_sites.items():
            site = sites[name]
            self.assertEqual(
                (
                    site["runtime_address"],
                    site["expected_size"],
                    site["expected_sha256"],
                    site["branch"],
                ),
                (*expected, "b_w"),
            )
            self.assertEqual(
                apollo_overlay.decode_thumb_branch(
                    site["runtime_address"],
                    bytes.fromhex(site["replacement_hex"])[:4],
                    link=False,
                ),
                site["target_address"],
            )

        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        application = base[32:]
        application_base = 0x00438000
        entries = {
            address: size
            for address, size, _digest in expected_sites.values()
        }
        references = {
            entry: {"bl": [], "bw": [], "words": [], "interior": []}
            for entry in entries
        }
        for offset in range(0, len(application) - 3, 2):
            address = application_base + offset
            encoded = application[offset:offset + 4]
            for link, kind in ((True, "bl"), (False, "bw")):
                try:
                    target = apollo_overlay.decode_thumb_branch(
                        address,
                        encoded,
                        link=link,
                    )
                except apollo_overlay.BuildError:
                    continue
                for entry, size in entries.items():
                    if target == entry:
                        references[entry][kind].append(address)
                    if entry < target < entry + size:
                        references[entry]["interior"].append(
                            (kind, address, target)
                        )
            value = struct.unpack_from("<I", application, offset)[0]
            for entry, size in entries.items():
                if value == (entry | 1):
                    references[entry]["words"].append(address)
                if value & 1 and entry < (value & ~1) < entry + size:
                    references[entry]["interior"].append(
                        ("pointer", address, value)
                    )

