        stored_words = []
        interior = []
        for offset in range(0, len(application) - 3, 2):
            address = application_base + offset
            encoded = application[offset:offset + 4]
            for link, collection, kind in (
                (True, callers, "bl"),
                (False, wide_callers, "bw"),
            ):
                try:
                    target = apollo_overlay.decode_thumb_branch(
                        address,
                        encoded,
                        link=link,
                    )
                except apollo_overlay.BuildError:
                    continue
                if target == 0x00476CBC:
                    collection.append(address)
                if 0x00476CBC < target < 0x00476DB8:
                    interior.append((kind, address, target))
            value = struct.unpack_from("<I", application, offset)[0]
            if value == 0x00476CBD:
                stored_words.append(address)
            if (
                value & 1
                and 0x00476CBC < (value & ~1) < 0x00476DB8
            ):
                interior.append(("pointer", address, value))

        self.assertEqual(callers, [0x00478448, 0x004784A8, 0x00478598])
