    def test_ble_connection_delayed_callback_executes_against_host_oracles(
        self,
    ) -> None:
        site = next(
            item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] == "replace_ble_connection_callback"
        )
        self.assertEqual(
            (
                site["runtime_address"],
                site["expected_size"],
                site["expected_sha256"],
                site["branch"],
            ),
            (
                0x0047761C,
                290,
                "3d0a02c39f02367e96100f7af48fdf6b4a511ef489f59963191664a13fcfddde",
                "b_w",
            ),
        )
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                site["runtime_address"],
                bytes.fromhex(site["replacement_hex"])[:4],
                link=False,
            ),
            site["target_address"],
        )

        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        application = base[32:]
        application_base = 0x00438000
        callers = []
        wide_callers = []
        stored_words = []
        interior = []
        for offset in range(0, len(application) - 3, 2):
            address = application_base + offset
            encoded = application[offset:offset + 4]
            for link, collection, kind in (
                (True, callers, "bl"),
                (False, wide_callers, "bw"),
            ):
                try:
                    target = apollo_overlay.decode_thumb_branch(
                        address,
                        encoded,
                        link=link,
                    )
                except apollo_overlay.BuildError:
                    continue
                if target == 0x0047761C:
                    collection.append(address)
                if 0x0047761C < target < 0x0047773E:
                    interior.append((kind, address, target))
            value = struct.unpack_from("<I", application, offset)[0]
            if value == 0x0047761D:
                stored_words.append(address)
            if (
                value & 1
                and 0x0047761C < (value & ~1) < 0x0047773E
            ):
                interior.append(("pointer", address, value))

        self.assertEqual(callers, [])
        self.assertEqual(wide_callers, [])
        self.assertEqual(
            stored_words,
            [0x00477758, 0x004782AC, 0x00478724],
        )
        self.assertEqual(
            hashlib.sha256(
                b"".join(
                    struct.pack("<I", address)
                    for address in stored_words
                )
            ).hexdigest(),
            "1caa79268e24793e5229a4860c11cef5289f72b639f372ba1b06f8f65d3b6ef3",
        )
        self.assertEqual(interior, [])

        function = self.component_report["overlay"]["functions"][
            "open_cfw_ble_connection_delayed_callback"
        ]
        self.assertEqual(function, {"offset": 49636, "size": 414})
        self.assertEqual(
            [
                relocation
                for relocation in self.component_report["overlay"]["link"][
                    "resolved_relocations"
                ]
                if 49636 <= relocation["site"] < 50050
            ],
            [],
        )

        source = COMPONENT_ROOT / "ble_connection_callback.c"
        fixture = (
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "ble_connection_callback_host.c"
        )
        self.assertEqual(
            hashlib.sha256(source.read_bytes()).hexdigest(),
            "ebffd89fd3d269d7f696f2f4d9684abdbd0a5dc0687e946c1f859c4690812d78",
        )
        self.assertEqual(
            hashlib.sha256(fixture.read_bytes()).hexdigest(),
            "93785eda9a6d6786d24eb6551fa9be767fdd90dbade2b1e2bbc324ef466de6e0",
        )

        with tempfile.TemporaryDirectory() as directory:
            library = Path(directory) / (
                "ble_connection_callback.dylib"
                if sys.platform == "darwin"
                else "ble_connection_callback.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
                "-dynamiclib" if sys.platform == "darwin" else "-shared",
                "-o",
                str(library),
            ]
            if sys.platform != "darwin":
                command.insert(-2, "-fPIC")
            subprocess.run(command, check=True, capture_output=True)
            loaded = ctypes.CDLL(str(library))

            reset = loaded.open_cfw_test_ble_callback_reset
            reset.argtypes = []
            reset.restype = None
            callback = (
                loaded.open_cfw_ble_connection_delayed_callback
            )
            callback.argtypes = [ctypes.c_uint] * 4
            callback.restype = ctypes.c_ulonglong

            def word(name: str) -> ctypes.c_uint:
                return ctypes.c_uint.in_dll(loaded, name)

            controller = (ctypes.c_ubyte * 0x57).in_dll(
                loaded,
                "open_cfw_test_ble_callback_controller_storage",
            )
            packet = (ctypes.c_ubyte * 12).in_dll(
                loaded,
                "open_cfw_test_ble_callback_packet",
            )
            levels = (ctypes.c_uint * 8).in_dll(
                loaded,
                "open_cfw_test_ble_callback_levels",
            )
            log_record = (ctypes.c_size_t * 7).in_dll(
                loaded,
                "open_cfw_test_ble_callback_log_record",
            )
            trace_record = (ctypes.c_size_t * 3).in_dll(
                loaded,
                "open_cfw_test_ble_callback_trace_record",
            )

            rejection_cases = (
                (
                    "controller",
                    1,
                    0x120,
                    0x00731604,
                    0x04000000,
                    0x007123E8,
                ),
                (
                    "context",
                    2,
                    0x125,
                    0x00726B80,
                    0x08000000,
                    0x00708EE4,
                ),
                (
                    "role",
                    2,
                    0x12A,
                    0x00751CD4,
                    0x08000000,
                    0x00731634,
                ),
            )
            for (
                rejection,
                level,
                line,
                message,
                trace_level,
                trace,
            ) in rejection_cases:
                reset()
                controller[0x56] = 5
                if rejection == "controller":
                    ctypes.c_void_p.in_dll(
                        loaded,
                        "open_cfw_test_ble_callback_controller_pointer",
                    ).value = None
                elif rejection == "context":
                    ctypes.c_void_p.in_dll(
                        loaded,
                        "open_cfw_test_ble_callback_context_pointer",
                    ).value = None
                else:
                    word(
                        "open_cfw_test_ble_callback_role_result"
                    ).value = 1
                levels[:2] = [7, 7]
                word("open_cfw_test_ble_callback_level_count").value = 2
                result = callback(
                    0x1A4,
                    0x11223344,
                    0x55667788,
                    0xCAFEBABE,
                )
                self.assertEqual(result, 0x5566778811223344)
                self.assertEqual(
                    list(log_record),
                    [
                        level,
                        0x0078A0B8,
                        0x006F81BC,
                        0x0077DD44,
                        line,
                        message,
                        0xCAFEBABE,
                    ],
                )
                self.assertEqual(
                    list(trace_record),
                    [trace_level, trace, trace],
                )
                self.assertEqual(
                    (
                        word(
                            "open_cfw_test_ble_callback_log_count"
                        ).value,
                        word(
                            "open_cfw_test_ble_callback_trace_count"
                        ).value,
                        word(
                            "open_cfw_test_ble_callback_allocate_calls"
                        ).value,
                    ),
                    (1, 1, 0),
                )

            reset()
            controller[0x56] = 5
            word("open_cfw_test_ble_callback_role_result").value = 1
            self.assertEqual(callback(0xA3, 1, 2, 3), 0x0000000200000001)
            self.assertEqual(
                (
                    word(
                        "open_cfw_test_ble_callback_role_calls"
                    ).value,
                    word(
                        "open_cfw_test_ble_callback_allocate_calls"
                    ).value,
                    word(
                        "open_cfw_test_ble_callback_allocate_size"
                    ).value,
                ),
                (1, 1, 12),
            )

            reset()
            controller[0x56] = 9
            ctypes.c_void_p.in_dll(
                loaded,
                "open_cfw_test_ble_callback_allocation_result",
            ).value = ctypes.addressof(packet)
            result = callback(0x1A4, 0x89ABCDEF, 0x01234567, 0)
            self.assertEqual(result, 0x0123456789ABCDEF)
            self.assertEqual(
                (
                    list(packet),
                    word(
                        "open_cfw_test_ble_callback_send_calls"
                    ).value,
                    ctypes.c_ubyte.in_dll(
                        loaded,
                        "open_cfw_test_ble_callback_send_endpoint",
                    ).value,
                    ctypes.c_size_t.in_dll(
                        loaded,
                        "open_cfw_test_ble_callback_send_packet",
                    ).value,
                ),
                (
                    [0, 0, 0xB9] + [0xA5] * 5
                    + [0xA4, 0] + [0xA5] * 2,
                    1,
                    9,
                    ctypes.addressof(packet),
                ),
            )

