    def test_mram_address_resolver_is_pinned_to_reviewed_stock_span(
        self,
    ) -> None:
        site = next(
            item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"]
            == "replace_mram_resolve_and_connect_by_address"
        )
        self.assertEqual(
            (
                site["runtime_address"],
                site["expected_size"],
                site["expected_sha256"],
                site["target_address"],
            ),
            (
                0x0047A8C4,
                650,
                "4e15e1759a0bd86fffa1b8cbbe81f5db7ec9b152c21a49b9f4a611535dad99a4",
                0x007A4624,
            ),
        )
        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        application = base[32:]
        application_base = 0x00438000
        function_start = 0x0047A8C4
        function_end = 0x0047AB4E
        self.assertEqual(
            hashlib.sha256(
                application[
                    function_start - application_base:
                    function_end - application_base
                ]
            ).hexdigest(),
            site["expected_sha256"],
        )
        self.assertEqual(
            hashlib.sha256(
                application[
                    0x0047AB4E - application_base:
                    0x0047AB6C - application_base
                ]
            ).hexdigest(),
            "a2ef08dda4c13efbc884b28e0679bfb256831559ef90ba7baa9646df02a61766",
        )
        self.assertEqual(
            application[
                0x0047AB6C - application_base:
                0x0047AB70 - application_base
            ].hex(),
            "78b589b0",
        )

        callers = []
        wide_entries = []
        external_interior_calls = []
        for offset in range(0, len(application) - 3, 2):
            address = application_base + offset
            encoded = application[offset:offset + 4]
            try:
                target = apollo_overlay.decode_thumb_branch(
                    address,
                    encoded,
                    link=True,
                )
            except apollo_overlay.BuildError:
                pass
            else:
                if target == function_start:
                    callers.append(address)
                if (
                    function_start < target < function_end
                    and not function_start <= address < function_end
                ):
                    external_interior_calls.append((address, target))
            try:
                target = apollo_overlay.decode_thumb_branch(
                    address,
                    encoded,
                    link=False,
                )
            except apollo_overlay.BuildError:
                continue
            if target == function_start:
                wide_entries.append(address)

        self.assertEqual(callers, [0x004A001C, 0x004A011C])
        self.assertEqual(
            hashlib.sha256(
                b"".join(struct.pack("<I", caller) for caller in callers)
            ).hexdigest(),
            "da17011580198f93a3c19de5e91c3b6f98d0424de0ed50466ffb5904012dde3d",
        )
        self.assertEqual(wide_entries, [])
        self.assertEqual(
            external_interior_calls,
            [(0x0067AE02, 0x0047AA0A)],
        )

        stored_entries = []
        stored_interior = []
        for offset in range(0, len(application) - 3):
            value = struct.unpack_from("<I", application, offset)[0]
            if value == (function_start | 1):
                stored_entries.append(application_base + offset)
            if (
                value & 1
                and function_start < (value & ~1) < function_end
            ):
                stored_interior.append(
                    (application_base + offset, value & ~1)
                )
        self.assertEqual(stored_entries, [])
        self.assertEqual(stored_interior, [])

        function = self.component_report["overlay"]["functions"][
            "open_cfw_mram_resolve_and_connect_by_address"
        ]
        self.assertEqual(function, {"offset": 66304, "size": 802})
        self.assertEqual(
            [
                relocation
                for relocation in self.component_report["overlay"]["link"][
                    "resolved_relocations"
                ]
                if 66304 <= relocation["site"] < 67106
            ],
            [],
        )
        overlay = (
            OPENCFW_ROOT
            / self.component_report["overlay"]["artifact"]
        ).read_bytes()
        compiled = overlay[66304:67106]
        self.assertEqual(
            hashlib.sha256(compiled).hexdigest(),
            "4cb871efbae94e766909d311841a32d8ce870184a0797deb1b37abbfa20a7f14",
        )
