    def test_mram_dump_all_records_is_pinned_to_stock_span(self) -> None:
        site = next(
            item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] == "replace_mram_dump_all_records"
        )
        self.assertEqual(
            (
                site["runtime_address"],
                site["expected_size"],
                site["expected_sha256"],
            ),
            (
                0x0047CA9C,
                34,
                "3e8460c8c262c212695243821d811daaf"
                "5cee4c0a4b1751dfe291251b606b068",
            ),
        )
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                site["runtime_address"],
                bytes.fromhex(site["replacement_hex"])[:4],
                link=False,
            ),
            site["target_address"],
        )

        function = self.component_report["overlay"]["functions"][
            "open_cfw_mram_dump_all_records"
        ]
        self.assertEqual(function, {"offset": 77832, "size": 30})

        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        application = base[32:]
        application_base = 0x00438000
        start = 0x0047CA9C
        end = 0x0047CABE
        stock = application[
            start - application_base:end - application_base
        ]
        self.assertEqual(len(stock), 34)
        self.assertEqual(
            stock.hex(),
            "38b548480468002506e02900c9b22000"
            "fbf780ffc8346d1c2800c0b20a28f4db31bd",
        )
        self.assertEqual(
            hashlib.sha256(stock).hexdigest(),
            "3e8460c8c262c212695243821d811daaf"
            "5cee4c0a4b1751dfe291251b606b068",
        )
        self.assertEqual(
            hashlib.sha256(stock[:16]).hexdigest(),
            "5e504d584aa6a72553069819a546f99be"
            "e2b66a60c478bfa83caf05c9b8a1fbb",
        )

        callers = []
        wide_entries = []
        interior_candidates = []
        for offset in range(0, len(application) - 3, 2):
            address = application_base + offset
            encoded = application[offset:offset + 4]
            for link, observed in (
                (True, callers),
                (False, wide_entries),
            ):
                try:
                    destination = apollo_overlay.decode_thumb_branch(
                        address,
                        encoded,
                        link=link,
                    )
                except apollo_overlay.BuildError:
                    continue
                if destination == start:
                    observed.append(address)
                if (
                    start < destination < end
                    and not start <= address < end
                ):
                    interior_candidates.append(
                        (address, destination, link)
                    )
        self.assertEqual(callers, [0x00581230])
        self.assertEqual(
            hashlib.sha256(
                b"".join(
                    struct.pack("<I", caller)
                    for caller in callers
                )
            ).hexdigest(),
            "86e860f6d17a1f0cad538134206fbb8b0"
            "1cade0a092231fb736228ebea1a5056",
        )
        self.assertEqual(wide_entries, [])
        self.assertEqual(interior_candidates, [])
        caller_context = application[
            0x00581224 - application_base:
            0x0058123C - application_base
        ]
        self.assertEqual(
            caller_context.hex(),
            "002806d1dff87c04f2f6dff8fbf634fc"
            "11e0dff874142000",
        )
        self.assertEqual(
            hashlib.sha256(caller_context).hexdigest(),
            "54d1b6f306115ae6572a1ad9ffabbaef"
            "423a8eb5eb42582bbd2bcec7da3c1b03",
        )

        stored_entries = []
        stored_interior = []
        for offset in range(0, len(application) - 3):
            value = struct.unpack_from("<I", application, offset)[0]
            if value == (start | 1):
                stored_entries.append(application_base + offset)
            if value & 1 and start < (value & ~1) < end:
                stored_interior.append(
                    (application_base + offset, value & ~1)
                )
        self.assertEqual(stored_entries, [])
        self.assertEqual(stored_interior, [])

        overlay = (
            OPENCFW_ROOT
            / self.component_report["overlay"]["artifact"]
        ).read_bytes()
        compiled = overlay[
            function["offset"]:function["offset"] + function["size"]
        ]
        self.assertEqual(
            hashlib.sha256(compiled).hexdigest(),
            "e74c05e5f4a0c612014770e2f37b69d5"
            "41d203a78a9f0746469d130057549d0c",
        )
        self.assertEqual(
            [
                (
                    relocation["site"],
                    relocation["symbol"],
                    relocation["type"],
                )
                for relocation in self.component_report["overlay"]["link"][
                    "resolved_relocations"
                ]
                if (
                    function["offset"]
                    <= relocation["site"]
                    < function["offset"] + function["size"]
                )
            ],
            [
                (
                    77850,
                    "open_cfw_mram_record_diagnostic_dump",
                    10,
                ),
            ],
        )

        following_pool = application[
            0x0047CABE - application_base:
            0x0047CBC4 - application_base
        ]
        self.assertEqual(len(following_pool), 262)
        self.assertEqual(
            hashlib.sha256(following_pool).hexdigest(),
            "0108c5e6aaf4b7cbf52668b594417cc7"
            "b6badf5e8c06ed5da6e515254f9605b7",
        )
        next_body = application[
            0x0047CBC4 - application_base:
            0x0047CBE8 - application_base
        ]
        self.assertEqual(len(next_body), 36)
        self.assertEqual(
            hashlib.sha256(next_body).hexdigest(),
            "bcccb282bc01b50eb187240b4de802095"
            "c6a6d4cbaeb8120da05972762cdcf70",
        )
        self.assertEqual(
            hashlib.sha256(
                (
                    COMPONENT_ROOT
                    / "mram_dump_all_records.c"
                ).read_bytes()
            ).hexdigest(),
            "7f7a5fa4fc680972e23332c4dd7aa95d"
            "e60ab6c24d1bf1e63c452ae5b2fadb60",
        )
        self.assertEqual(
            hashlib.sha256(
                (
                    OPENCFW_ROOT
                    / "tests"
                    / "fixtures"
                    / "mram_dump_all_records_host.c"
                ).read_bytes()
            ).hexdigest(),
            "5930be763ab264020cdb8cedca80e826b"
            "aaa9e2f849afbcdfa53784db257bbf9",
        )
        self.assertEqual(
            hashlib.sha256(
                (
                    OPENCFW_ROOT
                    / "tests"
                    / "test_mram_dump_all_records.py"
                ).read_bytes()
            ).hexdigest(),
            "aa346cecd993110a17a837bacc6e5ea7"
            "a2bc755c00b0b2510e585e9640c6bc3f",
        )

