    def test_boot_identity_helpers_are_pinned_to_stock_spans(
        self,
    ) -> None:
        sites = {
            item["name"]: item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] in {
                "replace_boot_reset_status",
                "replace_firmware_version_code",
            }
        }
        self.assertEqual(
            {
                name: (
                    item["runtime_address"],
                    item["expected_size"],
                    item["expected_sha256"],
                    item["target_function"],
                )
                for name, item in sites.items()
            },
            {
                "replace_boot_reset_status": (
                    0x0047DCEC,
                    28,
                    "7eb5083e1fd384179e48a8ee886411a2"
                    "4b67edf384778714a23ae458e7804258",
                    "open_cfw_reset_status_word",
                ),
                "replace_firmware_version_code": (
                    0x0047DD08,
                    90,
                    "3b5f57b6e725e2b0b4bb82525cfdfa87"
                    "f1ce244b263dc77f22c508a683c01760",
                    "open_cfw_firmware_version_code",
                ),
            },
        )
        for item in sites.values():
            self.assertEqual(
                apollo_overlay.decode_thumb_branch(
                    item["runtime_address"],
                    bytes.fromhex(item["replacement_hex"])[:4],
                    link=False,
                ),
                item["target_address"],
            )

        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        application = base[32:]
        application_base = 0x00438000
        spans = {
            0x0047DCEC: (
                0x0047DD08,
                [0x0048EB18],
                "406a834e565630ce199f8ced8cc5381af"
                "3f9c6b72ed8fdf5097cbee75acc0520",
            ),
            0x0047DD08: (
                0x0047DD62,
                [0x0048EB1E, 0x0048ED28],
                "e875517063b78664c7fd7c326e5732f4"
                "c785427fc0b783287bd0a15dc143acae",
            ),
        }
        for start, (end, expected_callers, caller_digest) in spans.items():
            direct_callers = []
            wide_callers = []
            external_interior = []
            for offset in range(0, len(application) - 3, 2):
                address = application_base + offset
                encoded = application[offset:offset + 4]
                for link, observed in (
                    (True, direct_callers),
                    (False, wide_callers),
                ):
                    try:
                        target = apollo_overlay.decode_thumb_branch(
                            address,
                            encoded,
                            link=link,
                        )
                    except apollo_overlay.BuildError:
                        continue
                    if target == start:
                        observed.append(address)
                    if (
                        start < target < end
                        and not start <= address < end
                    ):
                        external_interior.append(
                            (address, target, link)
                        )
            self.assertEqual(direct_callers, expected_callers)
            self.assertEqual(wide_callers, [])
            self.assertEqual(external_interior, [])
            self.assertEqual(
                hashlib.sha256(
                    b"".join(
                        struct.pack("<I", caller)
                        for caller in direct_callers
                    )
                ).hexdigest(),
                caller_digest,
            )

            stored_entries = []
            stored_interior = []
            for offset in range(0, len(application) - 3):
                value = struct.unpack_from("<I", application, offset)[0]
                if value == (start | 1):
                    stored_entries.append(application_base + offset)
                if value & 1 and start < (value & ~1) < end:
                    stored_interior.append(
                        (application_base + offset, value & ~1)
                    )
            self.assertEqual(stored_entries, [])
            self.assertEqual(stored_interior, [])

        reset_stock = application[
            0x0047DCEC - application_base:
            0x0047DD08 - application_base
        ]
        version_stock = application[
            0x0047DD08 - application_base:
            0x0047DD62 - application_base
        ]
        self.assertEqual(
            hashlib.sha256(reset_stock).hexdigest(),
            sites["replace_boot_reset_status"]["expected_sha256"],
        )
        self.assertEqual(
            hashlib.sha256(version_stock).hexdigest(),
            sites["replace_firmware_version_code"]["expected_sha256"],
        )
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                0x0047DCF6,
                reset_stock[10:14],
                link=True,
            ),
            0x0043C0E4,
        )
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                0x0047DCFC,
                reset_stock[16:20],
                link=True,
            ),
            0x004D3554,
        )
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                0x0047DD26,
                version_stock[30:34],
                link=True,
            ),
            0x0048D874,
        )
        version_pointer = struct.unpack_from(
            "<I",
            application,
            0x0047E288 - application_base,
        )[0]
        self.assertEqual(version_pointer, 0x0078C740)
        version_offset = version_pointer - application_base
        self.assertEqual(
            application[version_offset:version_offset + 9],
            b"2.2.6.10\0",
        )
        self.assertEqual(
            hashlib.sha256(
                application[version_offset:version_offset + 9]
            ).hexdigest(),
            "1d27c626899ff09293628ff85e00799e"
            "b7490e039232b54c4fb8528554fe3ef1",
        )
        self.assertEqual(
            hashlib.sha256(
                application[
                    0x0048EB12 - application_base:
                    0x0048EB30 - application_base
                ]
            ).hexdigest(),
            "c0337f0abbf6f50db27590341e1d0fb6"
            "f3afcf3fc5cac6b59eaee1a9073e4a1b",
        )

        overlay = (
            OPENCFW_ROOT / self.component_report["overlay"]["artifact"]
        ).read_bytes()
        compiled_expectations = {
            "open_cfw_reset_status_word": (
                {"offset": 79824, "size": 100},
                "4aaee1a7870e80e0a91b1df5a90c3979"
                "428bbfe45af86b3e08fdd4fb1d243f83",
            ),
            "open_cfw_firmware_version_code": (
                {"offset": 79924, "size": 174},
                "a53973906163e4289904fe682d1fc10ef"
                "8eb34a83179b413574b36f062c33c84",
            ),
        }
        functions = self.component_report["overlay"]["functions"]
        for name, (expected_function, digest) in (
            compiled_expectations.items()
        ):
            function = functions[name]
            self.assertEqual(function, expected_function)
            compiled = overlay[
                function["offset"]:
                function["offset"] + function["size"]
            ]
            self.assertEqual(
                hashlib.sha256(compiled).hexdigest(),
                digest,
            )
        self.assertEqual(
            [
                (
                    relocation["site"],
                    relocation["symbol"],
                    relocation["type"],
                )
                for relocation in self.component_report["overlay"]["link"][
                    "resolved_relocations"
                ]
                if 79824 <= relocation["site"] < 80098
            ],
            [
                (79940, ".L.str.1", 49),
                (79944, ".L.str.1", 50),
            ],
        )

        pinned_files = {
            COMPONENT_ROOT / "boot_identity.c":
                "c61ddd0a30dfac196f7147ffb054c29e"
                "bbb66637d9de9e57d5466c4979886f7c",
            OPENCFW_ROOT / "tests" / "fixtures" / "boot_identity_host.c":
                "edf4e44114ea595c8051aa6d54db945d"
                "0520720ef960e9dd8e03a00257c780ea",
            OPENCFW_ROOT / "tests" / "test_boot_identity.py":
                "093084ced2612c332cc0aa67d076ed55"
                "18f544814cbe8f5595d325203503df08",
        }
        for path, digest in pinned_files.items():
            self.assertEqual(
                hashlib.sha256(path.read_bytes()).hexdigest(),
                digest,
            )

