            address = application_base + offset
            instruction = struct.unpack_from(
                "<H",
                application,
                offset,
            )[0]
            targets = []
            if instruction & 0xF800 == 0xE000:
                immediate = (instruction & 0x07FF) << 1
                if immediate & 0x0800:
                    immediate -= 0x1000
                targets.append(address + 4 + immediate)
            if (
                instruction & 0xF000 == 0xD000
                and ((instruction >> 8) & 0x0F) < 0x0E
            ):
                immediate = (instruction & 0x00FF) << 1
                if immediate & 0x0100:
                    immediate -= 0x0200
                targets.append(address + 4 + immediate)
            if instruction & 0xF500 == 0xB100:
                immediate = (
                    (((instruction >> 9) & 1) << 6)
                    | (((instruction >> 3) & 0x1F) << 1)
                )
                targets.append(address + 4 + immediate)
            for target in targets:
                if (
                    start <= target < end
                    and not start <= address < end
                ):
                    narrow_interior.append((address, target))
