        for offset in range(0, len(application) - 3, 2):
            address = application_base + offset
            encoded = application[offset:offset + 4]
            for link, observed in (
                (True, direct_callers),
                (False, wide_jumps),
            ):
                try:
                    target = apollo_overlay.decode_thumb_branch(
                        address,
                        encoded,
                        link=link,
                    )
                except apollo_overlay.BuildError:
                    continue
                if target == start:
                    observed.append(address)
                if (
                    start < target < end
                    and not start <= address < end
                ):
                    external_interior.append(
                        (address, target, link)
                    )
        self.assertEqual(direct_callers, [0x0044A20C])
        self.assertEqual(wide_jumps, [])
        self.assertEqual(external_interior, [])

        narrow_interior = []
        for offset in range(0, len(application) - 1, 2):
            address = application_base + offset
            instruction = struct.unpack_from(
                "<H",
                application,
                offset,
            )[0]
            targets = []
            if instruction & 0xF800 == 0xE000:
                immediate = (instruction & 0x07FF) << 1
                if immediate & 0x0800:
                    immediate -= 0x1000
                targets.append(address + 4 + immediate)
            if (
                instruction & 0xF000 == 0xD000
                and ((instruction >> 8) & 0x0F) < 0x0E
            ):
                immediate = (instruction & 0x00FF) << 1
                if immediate & 0x0100:
                    immediate -= 0x0200
                targets.append(address + 4 + immediate)
            if instruction & 0xF500 == 0xB100:
                immediate = (
                    (((instruction >> 9) & 1) << 6)
                    | (((instruction >> 3) & 0x1F) << 1)
                )
                targets.append(address + 4 + immediate)
            for target in targets:
                if (
                    start <= target < end
                    and not start <= address < end
                ):
                    narrow_interior.append((address, target))
        self.assertEqual(narrow_interior, [])

        stored_entries = []
        stored_interior = []
        for offset in range(0, len(application) - 3):
            value = struct.unpack_from("<I", application, offset)[0]
            if value == (start | 1):
                stored_entries.append(application_base + offset)
            if value & 1 and start < (value & ~1) < end:
                stored_interior.append(
                    (application_base + offset, value & ~1)
                )
        self.assertEqual(stored_entries, [])
        self.assertEqual(stored_interior, [])

