    def test_spotmgr_initializer_is_source_owned(self) -> None:
        stock_address = 0x00480434
        stock_end = 0x004806D0
        stock_size = stock_end - stock_address
        site = next(
            item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] == "replace_spotmgr_init"
        )
        self.assertEqual(
            (
                site["runtime_address"],
                site["expected_size"],
                site["expected_sha256"],
                site["target_function"],
            ),
            (
                stock_address,
                stock_size,
                "892f39cd717b6f7ef3218fc23730c1ac"
                "2e2d10143effd59eedb6584b412dfd83",
                "open_cfw_spotmgr_init",
            ),
        )

        replacement = bytes.fromhex(site["replacement_hex"])
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                stock_address,
                replacement[:4],
                link=False,
            ),
            site["target_address"],
        )
        self.assertEqual(
            replacement[4:],
            b"\x00\xBF" * ((stock_size - 4) // 2),
        )
        self.assertEqual(
            hashlib.sha256(replacement).hexdigest(),
            "7bc5b1d2f691f625f5ed0242bc55f00f"
            "4f1a0fab5e1f829293614cd05b20f5a6",
        )

        function = self.component_report["overlay"]["functions"][
            "open_cfw_spotmgr_init"
        ]
        self.assertEqual(function, {"offset": 91520, "size": 720})
        overlay = (
            OPENCFW_ROOT / self.component_report["overlay"]["artifact"]
        ).read_bytes()
        compiled = overlay[
            function["offset"]:function["offset"] + function["size"]
        ]
        self.assertEqual(
            hashlib.sha256(compiled).hexdigest(),
            "26e5bb24644df7d1c2d3592a43043c57"
            "d05193709820c9dc702681dff87ff08a",
        )
        self.assertEqual(
            [
                relocation
                for relocation in self.component_report["overlay"]["link"][
                    "resolved_relocations"
                ]
                if function["offset"]
                <= relocation["site"]
                < function["offset"] + function["size"]
            ],
            [],
        )

        official = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()[32:]
        base = 0x00438000
        body = official[stock_address - base:stock_end - base]
        pool = official[stock_end - base:0x004807A0 - base]
        self.assertEqual(
            hashlib.sha256(body).hexdigest(),
            "892f39cd717b6f7ef3218fc23730c1ac"
            "2e2d10143effd59eedb6584b412dfd83",
        )
        self.assertEqual(len(pool), 208)
        self.assertEqual(
            hashlib.sha256(pool).hexdigest(),
            "d2ee77b38e4e3b895fa544672c1f244e"
            "13ac0ccce2afeff1b626758d2bbdf162",
        )
        handler_table = official[
            0x0048072C - base:0x004807A0 - base
        ]
        self.assertEqual(
            hashlib.sha256(handler_table).hexdigest(),
            "4e8425ee94ea1c0e3e94aff01227d696"
            "4d4d94223553911814c78f9e2083b858",
        )
        self.assertEqual(
            struct.unpack("<29I", handler_table),
            (
                0x005A4D49, 0x005A490D, 0x005A4E0D,
                0x005A4D01, 0x005A40B7, 0x005A40CB,
                0x005A1C19, 0x005A1739, 0x005A1DA5,
                0x005A1BBD, 0x005A1BCD, 0x005A1BED,
                0x005A0BCD, 0x005A08E5, 0x005A0787,
                0x005A0A6D, 0x005A07E7, 0x005A07F1,
                0x005A085F, 0x005A08B7, 0x005A08CB,
                0x0059FD83, 0x0059FDA9, 0x005A081D,
                0x005A0843, 0x005A0019, 0x0059FD37,
                0x0059FDC3, 0x0059FE5B,
            ),
        )

        calls = []
        jumps = []
        external_interior = []
        dependencies = []
        for offset in range(0, len(official) - 3, 2):
            address = base + offset
            encoded = official[offset:offset + 4]
            for link, observed in ((True, calls), (False, jumps)):
                try:
                    target = apollo_overlay.decode_thumb_branch(
                        address,
                        encoded,
                        link=link,
                    )
                except apollo_overlay.BuildError:
                    continue
                if target == stock_address:
                    observed.append(address)
                if (
                    stock_address < target < stock_end
                    and not stock_address <= address < stock_end
                ):
                    external_interior.append((address, target, link))
                if link and stock_address <= address < stock_end:
                    dependencies.append((address, target))
        self.assertEqual(calls, [0x0047FBB2])
        self.assertEqual(jumps, [])
        self.assertEqual(external_interior, [])
        self.assertEqual(dependencies, [(0x00480444, 0x0043C0E4)])

        stored = []
        for offset in range(0, len(official) - 3, 4):
            value = struct.unpack_from("<I", official, offset)[0]
            target = value & ~1
            if value & 1 and stock_address <= target < stock_end:
                stored.append((base + offset, target))
        self.assertEqual(stored, [])

        source_text = (COMPONENT_ROOT / "spotmgr_init.c").read_text()
        for token in (
            "OPEN_CFW_SPOTMGR_INIT_STATE_ADDRESS 0x20073270U",
            "OPEN_CFW_SPOTMGR_INIT_IS_PCM2P1_ADDRESS 0x20074F64U",
            "OPEN_CFW_SPOTMGR_INIT_INFO1_PATCH_TRACKER0_OFFSET 0x34U",
            "OPEN_CFW_SPOTMGR_INIT_ACRG_POWER_DOWN 0x00000002U",
            "OPEN_CFW_SPOTMGR_INIT_ANALDO_ACTIVE 0x00008000U",
            "OPEN_CFW_SPOTMGR_INIT_PCM2P2_INIT 0x005A4D49U",
            "OPEN_CFW_SPOTMGR_INIT_PCM2P1_INIT 0x005A1C19U",
            "OPEN_CFW_SPOTMGR_INIT_PCM2P0_INIT 0x005A08E5U",
            "OPEN_CFW_SPOTMGR_INIT_PCM0P7_INIT 0x005A0019U",
            "offset < OPEN_CFW_SPOTMGR_INIT_STATE_SIZE",
            "OPEN_CFW_SPOTMGR_INIT_READ_HANDLER(",
            "OPEN_CFW_SPOTMGR_INIT_CALL_HANDLER(handler)",
        ):
            self.assertIn(token, source_text)

        apollo_main = next(
            item
            for item in self.manifest["components"]
            if item["name"] == "apollo_main"
        )
        names = {
            "spotmgr_init_source_replacement",
            "spotmgr_shared_and_initializer_literal_pool",
            "duration_delay_source_replacement",
        }
        region_records = {
            item["name"]: (
                item["file_offset"],
                item["size"],
                item.get("target_address"),
                item["address_status"],
            )
            for item in apollo_main["regions"]
            if item["name"] in names
        }
        self.assertEqual(
            region_records,
            {
                "spotmgr_init_source_replacement": (
                    296020,
                    668,
                    0x00480434,
                    "generated_source_entry_replacement",
                ),
                "spotmgr_shared_and_initializer_literal_pool": (
                    296688,
                    208,
                    0x004806D0,
                    "official_blob",
                ),
                "duration_delay_source_replacement": (
                    296896,
                    92,
                    0x004807A0,
                    "generated_source_exact_replacement",
                ),
            },
        )

        pinned_files = {
            COMPONENT_ROOT / "spotmgr_init.c":
                "0f5e08e17b869bd6ddf6ba1ad25b05a4"
                "b98f8c6ebd9f869999e1a2505b28fb67",
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "spotmgr_init_host.c":
                "958fe39da7cc0d30ada46120e2627b22c"
                "7645dbc9accfe2c2df7f8c2272dee34",
            OPENCFW_ROOT / "tests" / "test_spotmgr_init.py":
                "cb06bea1571be4a21e503c7aaa2a9ec5"
                "3ab0e6bfcd14774fbf75338dc52556e8",
        }
        for path, digest in pinned_files.items():
            self.assertEqual(
                hashlib.sha256(path.read_bytes()).hexdigest(),
                digest,
            )

