    def test_lv_initialize_executes_against_host_oracles(
        self,
    ) -> None:
        site = next(
            item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] == "replace_lv_initialize"
        )
        self.assertEqual(
            (
                site["runtime_address"],
                site["expected_size"],
                site["expected_sha256"],
            ),
            (
                0x00473548,
                222,
                "864a6ef89d19b8f7dfb79aa84d4f85cf0df9fd1043a9f9104ad30c00c402fe33",
            ),
        )
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                site["runtime_address"],
                bytes.fromhex(site["replacement_hex"])[:4],
                link=False,
            ),
            site["target_address"],
        )

        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        application = base[32:]
        run_base = 0x00438000
        direct_callers = []
        for offset in range(0, len(application) - 3, 2):
            address = run_base + offset
            try:
                target = apollo_overlay.decode_thumb_branch(
                    address,
                    application[offset:offset + 4],
                    link=True,
                )
            except apollo_overlay.BuildError:
                continue
            if target == 0x00473548:
                direct_callers.append(address)
        self.assertEqual(direct_callers, [0x00444696])

        function = self.component_report["overlay"]["functions"][
            "open_cfw_lv_initialize"
        ]
        self.assertEqual(function, {"offset": 25912, "size": 390})
        self.assertEqual(
            [
                (
                    relocation["site"],
                    relocation["symbol"],
                    relocation["type"],
                )
                for relocation in self.component_report["overlay"]["link"][
                    "resolved_relocations"
                ]
                if (
                    function["offset"]
                    <= relocation["site"]
                    < function["offset"] + function["size"]
                )
            ],
            [
                (26006, "open_cfw_lv_global_initialize", 10),
                (26148, "open_cfw_lv_init_utf8_text", 49),
                (26152, "open_cfw_lv_init_utf8_text", 50),
            ],
        )

        source_path = COMPONENT_ROOT / "lv_init.c"
        self.assertEqual(
            hashlib.sha256(source_path.read_bytes()).hexdigest(),
            "286acb662fc2ec3c328fb5b51dddb34ca8b9f7a995eb91f6b1200a4c275ed6fc",
        )
        fixture = (
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "lv_init_host.c"
        )
        self.assertEqual(
            hashlib.sha256(fixture.read_bytes()).hexdigest(),
            "f1b8d1698a02c977f6adf9e1921090b4e22991ce482e8911641ad5f7034cd6e5",
        )

        with tempfile.TemporaryDirectory() as directory:
            library = Path(directory) / (
                "lv_init.dylib"
                if sys.platform == "darwin"
                else "lv_init.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))
            initialize = loaded.open_cfw_lv_initialize
            initialize.argtypes = []
            initialize.restype = None

            def word(name: str) -> ctypes.c_uint:
                return ctypes.c_uint.in_dll(loaded, name)

            lv_global = (ctypes.c_ubyte * 0x1EC).in_dll(
                loaded,
                "open_cfw_test_lv_init_global",
            )
            utf8 = (ctypes.c_ubyte * 3).in_dll(
                loaded,
                "open_cfw_test_lv_init_utf8_text",
            )
            endian = ctypes.c_ubyte.in_dll(
                loaded,
                "open_cfw_test_lv_init_endian_first_byte",
            )
            step_addresses = (ctypes.c_size_t * 20).in_dll(
                loaded,
                "open_cfw_test_lv_init_step_addresses",
            )
            step_first = (ctypes.c_uint * 20).in_dll(
                loaded,
                "open_cfw_test_lv_init_step_first",
            )
            step_second = (ctypes.c_uint * 20).in_dll(
                loaded,
                "open_cfw_test_lv_init_step_second",
            )
            log_arguments = (ctypes.c_void_p * 3).in_dll(
                loaded,
                "open_cfw_test_lv_init_log_arguments",
            )
            expected_steps = [
                0x0048AA61,
                0x004C6D05,
                0x0049ACB1,
                0x00464331,
                0x004C6D8D,
                0x004546DD,
                0x004503A5,
                0x0044D32D,
                0x004B1B99,
                0x0048438D,
                0x004C73D7,
                0x0044B90D,
                0x00488F4D,
                0x004C794D,
                0x004C8F0B,
                0x004C8EFD,
                0x004C91A9,
            ]

            def reset() -> None:
                ctypes.memset(ctypes.addressof(lv_global), 0, len(lv_global))
                utf8[:] = (0xC3, 0x81, 0)
                endian.value = 0x44
                for name in (
                    "open_cfw_test_lv_init_global_calls",
                    "open_cfw_test_lv_init_step_calls",
                    "open_cfw_test_lv_init_log_calls",
                    "open_cfw_test_lv_init_log_level",
                    "open_cfw_test_lv_init_log_line",
                    "open_cfw_test_lv_init_fatal_calls",
                ):
                    word(name).value = 0
                for name in (
                    "open_cfw_test_lv_init_global_pointer",
                    "open_cfw_test_lv_init_log_file",
                    "open_cfw_test_lv_init_log_function",
                ):
                    ctypes.c_void_p.in_dll(loaded, name).value = None
                for index in range(20):
                    step_addresses[index] = 0
                    step_first[index] = 0
                    step_second[index] = 0
                for index in range(3):
                    log_arguments[index] = None

            def assert_steps(count: int) -> None:
                self.assertEqual(
                    word("open_cfw_test_lv_init_step_calls").value,
                    count,
                )
                self.assertEqual(
                    list(step_addresses)[:count],
                    expected_steps[:count],
                )

            def assert_log(
                level: int,
                line: int,
                arguments: list[int],
            ) -> None:
                self.assertEqual(
                    word("open_cfw_test_lv_init_log_level").value,
                    level,
                )
                self.assertEqual(
                    ctypes.c_void_p.in_dll(
                        loaded,
                        "open_cfw_test_lv_init_log_file",
                    ).value,
                    0x006EE148,
                )
                self.assertEqual(
                    word("open_cfw_test_lv_init_log_line").value,
                    line,
                )
                self.assertEqual(
                    ctypes.c_void_p.in_dll(
                        loaded,
                        "open_cfw_test_lv_init_log_function",
                    ).value,
                    0x0078DC04,
                )
                self.assertEqual(
                    list(log_arguments)[:len(arguments)],
                    arguments,
                )

            reset()
            initialize()
            self.assertEqual(
                word("open_cfw_test_lv_init_global_calls").value,
                1,
            )
            self.assertEqual(
                ctypes.c_void_p.in_dll(
                    loaded,
                    "open_cfw_test_lv_init_global_pointer",
                ).value,
                ctypes.addressof(lv_global),
            )
            assert_steps(17)
            expected_first = [0] * 17
            expected_first[8] = 0x40
            expected_first[15] = 0x20071AC8
            self.assertEqual(list(step_first)[:17], expected_first)
            self.assertEqual(list(step_second)[:17], [0] * 17)
            self.assertEqual(
                word("open_cfw_test_lv_init_log_calls").value,
                0,
            )
            self.assertEqual(
                word("open_cfw_test_lv_init_fatal_calls").value,
                0,
            )
            self.assertEqual(lv_global[0], 1)

            reset()
            lv_global[0] = 1
            initialize()
            self.assertEqual(
                word("open_cfw_test_lv_init_global_calls").value,
                0,
            )
            assert_steps(0)
            self.assertEqual(
                word("open_cfw_test_lv_init_log_calls").value,
                1,
            )
            assert_log(2, 0xB9, [0x00761B90])
            self.assertEqual(lv_global[0], 1)

            reset()
            utf8[1] = 0
            initialize()
            assert_steps(17)
            self.assertEqual(
                word("open_cfw_test_lv_init_log_calls").value,
                1,
            )
            assert_log(2, 0x12C, [0x006EE198])
            self.assertEqual(
                word("open_cfw_test_lv_init_fatal_calls").value,
                0,
            )
            self.assertEqual(lv_global[0], 1)

            reset()
            endian.value = 0x11
            initialize()
            assert_steps(14)
            self.assertEqual(
                word("open_cfw_test_lv_init_log_calls").value,
                1,
            )
            assert_log(
                3,
                0x135,
                [0x00761B70, 0x0076DBB8, 0x006EE1E8],
            )
            self.assertEqual(
                word("open_cfw_test_lv_init_fatal_calls").value,
                1,
            )
            self.assertEqual(lv_global[0], 0)

