        with tempfile.TemporaryDirectory() as directory:
            library = Path(directory) / (
                "lv_global.dylib"
                if sys.platform == "darwin"
                else "lv_global.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))
            initialize = loaded.open_cfw_lv_global_initialize
            initialize.argtypes = [ctypes.c_void_p]
            initialize.restype = None

            def word(name: str) -> ctypes.c_uint:
                return ctypes.c_uint.in_dll(loaded, name)

            list_pointers = (ctypes.c_void_p * 2).in_dll(
                loaded,
                "open_cfw_test_lv_global_list_pointers",
            )
            list_sizes = (ctypes.c_uint * 2).in_dll(
                loaded,
                "open_cfw_test_lv_global_list_sizes",
            )
            log_arguments = (ctypes.c_void_p * 4).in_dll(
                loaded,
                "open_cfw_test_lv_global_log_arguments",
            )

            def reset() -> None:
                for name in (
                    "open_cfw_test_lv_global_list_calls",
                    "open_cfw_test_lv_global_finalize_calls",
                    "open_cfw_test_lv_global_finalize_cookie",
                    "open_cfw_test_lv_global_log_calls",
                    "open_cfw_test_lv_global_log_level",
                    "open_cfw_test_lv_global_log_line",
                    "open_cfw_test_lv_global_fatal_calls",
                ):
                    word(name).value = 0
                for name in (
                    "open_cfw_test_lv_global_log_file",
                    "open_cfw_test_lv_global_log_function",
                ):
                    ctypes.c_void_p.in_dll(loaded, name).value = None
                for index in range(2):
                    list_pointers[index] = None
                    list_sizes[index] = 0
                for index in range(4):
                    log_arguments[index] = None

            reset()
            buffer = (ctypes.c_ubyte * (0x1EC + 8))(
                *([0xA5] * (0x1EC + 8))
            )
            address = ctypes.addressof(buffer)
            initialize(address)
            self.assertEqual(
                word("open_cfw_test_lv_global_list_calls").value,
                2,
            )
            self.assertEqual(
                list(list_pointers),
                [address + 4, address + 0x44],
            )
            self.assertEqual(list(list_sizes), [0x31C, 0xDC])
            self.assertEqual(
                word("open_cfw_test_lv_global_finalize_calls").value,
                1,
            )
            self.assertEqual(
                word("open_cfw_test_lv_global_finalize_cookie").value,
                0x1234ABCD,
            )
            self.assertEqual(
                word("open_cfw_test_lv_global_log_calls").value,
                0,
            )
            self.assertEqual(
                word("open_cfw_test_lv_global_fatal_calls").value,
                0,
            )
            expected = bytearray(0x1EC)
            expected[0x24] = 1
            struct.pack_into("<I", expected, 0x2C, 0x89)
            struct.pack_into("<I", expected, 0x58, 3)
            struct.pack_into("<I", expected, 0x64, 0xA1B2C3D4)
            struct.pack_into("<I", expected, 0x70, 0x42)
            self.assertEqual(bytes(buffer[:0x1EC]), bytes(expected))
            self.assertEqual(bytes(buffer[0x1EC:]), b"\xA5" * 8)

            reset()
            initialize(None)
            self.assertEqual(
                word("open_cfw_test_lv_global_list_calls").value,
                0,
            )
            self.assertEqual(
                word("open_cfw_test_lv_global_finalize_calls").value,
                0,
            )
            self.assertEqual(
                word("open_cfw_test_lv_global_log_calls").value,
                1,
            )
            self.assertEqual(
                word("open_cfw_test_lv_global_log_level").value,
                3,
            )
            self.assertEqual(
                ctypes.c_void_p.in_dll(
                    loaded,
                    "open_cfw_test_lv_global_log_file",
                ).value,
                0x006EE148,
            )
            self.assertEqual(
                word("open_cfw_test_lv_global_log_line").value,
                0x7C,
            )
            self.assertEqual(
                ctypes.c_void_p.in_dll(
                    loaded,
                    "open_cfw_test_lv_global_log_function",
                ).value,
                0x007874E0,
            )
            self.assertEqual(
                list(log_arguments),
                [0x00761B70, 0x007874F0, 0x00787500, None],
            )
            self.assertEqual(
                word("open_cfw_test_lv_global_fatal_calls").value,
                1,
            )

