    def test_log_format_float_executes_against_host_oracles(
        self,
    ) -> None:
        site = next(
            item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] == "replace_log_float_write"
        )
        self.assertEqual(
            (
                site["runtime_address"],
                site["expected_size"],
                site["expected_sha256"],
            ),
            (
                0x00472EF6,
                320,
                "9feeff56d54c8a2e2ac1c7dbbff6f3c605085855d13fb143e23373e3921aa125",
            ),
        )
        self.assertEqual(
            apollo_overlay.decode_thumb_branch(
                site["runtime_address"],
                bytes.fromhex(site["replacement_hex"])[:4],
                link=False,
            ),
            site["target_address"],
        )

        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        application = base[32:]
        run_base = 0x00438000
        direct_callers = []
        for offset in range(0, len(application) - 3, 2):
            address = run_base + offset
            try:
                target = apollo_overlay.decode_thumb_branch(
                    address,
                    application[offset:offset + 4],
                    link=True,
                )
            except apollo_overlay.BuildError:
                continue
            if target == 0x00472EF6:
                direct_callers.append(address)
        self.assertEqual(direct_callers, [0x0047339E])

        function = self.component_report["overlay"]["functions"][
            "open_cfw_log_float_write"
        ]
        self.assertEqual(function, {"offset": 24932, "size": 562})
        self.assertEqual(
            [
                (
                    relocation["site"],
                    relocation["symbol"],
                    relocation["type"],
                )
                for relocation in self.component_report["overlay"]["link"][
                    "resolved_relocations"
                ]
                if (
                    function["offset"]
                    <= relocation["site"]
                    < function["offset"] + function["size"]
                )
            ],
            [(25088, "open_cfw_log_decimal_write", 10)],
        )

        source_path = COMPONENT_ROOT / "log_format_float.c"
        self.assertEqual(
            hashlib.sha256(source_path.read_bytes()).hexdigest(),
            "59d6067b2196f8a7c1e9d64dee537a62bc8d87c4211b1cd70261daee08f71bdd",
        )
        source = source_path.read_text()
        self.assertIn('pcs("aapcs-vfp")', source)
        self.assertNotIn("__aeabi", source)

        fixture = (
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "log_format_float_host.c"
        )
        self.assertEqual(
            hashlib.sha256(fixture.read_bytes()).hexdigest(),
            "f4b5ae720aa4b24c32b325fb59820a5e89074ca78d49b008e6ca8ba40b628724",
        )

        def signed32(value: int) -> int:
            value &= 0xFFFFFFFF
            return value - 0x100000000 if value >= 0x80000000 else value

        def reference(
            capacity: int,
            precision: int,
            bits: int,
        ) -> tuple[int, bytes | None]:
            if capacity < 4:
                return -3, None
            if bits & 0x7FFFFFFF == 0:
                return 3, b"0.0"

            exponent = ((bits >> 23) & 0xFF) - 127
            mantissa = (bits & 0x00FFFFFF) | 0x00800000
            if exponent >= 31:
                return -2, None
            if exponent < -23:
                return -1, None

            whole = 0
            fraction = 0
            if exponent >= 23:
                whole = (
                    mantissa << (exponent - 23)
                ) & 0xFFFFFFFF
            elif exponent >= 0:
                whole = mantissa >> (23 - exponent)
                fraction = (
                    mantissa << (exponent + 1)
                ) & 0x00FFFFFF
            else:
                fraction = mantissa >> (-(exponent + 1))

            output: list[int] = []
            if bits & 0x80000000:
                output.append(ord("-"))
            if whole == 0:
                output.append(ord("0"))
            else:
                if signed32(whole) < 0:
                    output.append(ord("-"))
                    whole = (-whole) & 0xFFFFFFFF
                output.extend(str(whole).encode("ascii"))
            output.append(ord("."))

            if fraction == 0:
                output.append(ord("0"))
            else:
                available = capacity - len(output) - 1
                if signed32(precision) >= available:
                    precision = available & 0xFFFFFFFF
                index = 0
                while signed32(index) < signed32(precision):
                    fraction = (fraction * 10) & 0xFFFFFFFF
                    output.append(ord("0") + signed32(fraction) // 0x1000000)
                    fraction &= 0x00FFFFFF
                    index = (index + 1) & 0xFFFFFFFF
                fraction = (fraction * 10) & 0xFFFFFFFF
                if signed32(fraction) // 0x1000000 >= 5:
                    rounding = len(output)
                    while rounding != 0:
                        rounding -= 1
                        if output[rounding] == ord("."):
                            continue
                        if output[rounding] == ord("9"):
                            output[rounding] = ord("0")
                            continue
                        output[rounding] += 1
                        break
            return len(output), bytes(output)

        with tempfile.TemporaryDirectory() as directory:
            library = Path(directory) / (
                "log_format_float.dylib"
                if sys.platform == "darwin"
                else "log_format_float.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))
            run = loaded.open_cfw_log_float_write
            run.argtypes = [
                ctypes.c_void_p,
                ctypes.c_uint,
                ctypes.c_float,
            ]
            run.restype = ctypes.c_int

            def execute(
                capacity: int,
                precision: int,
                bits: int,
            ) -> tuple[int, bytes | None]:
                buffer = (ctypes.c_ubyte * 80)(*([0xCC] * 80))
                capacity_bytes = struct.pack("<I", capacity)
                for index, byte in enumerate(capacity_bytes):
                    buffer[index] = byte
                before = bytes(buffer)
                value = struct.unpack("<f", struct.pack("<I", bits))[0]
                result = int(
                    run(
                        ctypes.addressof(buffer),
                        precision,
                        ctypes.c_float(value),
                    )
                )
                if result < 0:
                    self.assertEqual(bytes(buffer), before)
                    return result, None
                self.assertEqual(buffer[result], 0)
                self.assertEqual(
                    bytes(buffer[capacity:]),
                    b"\xCC" * (80 - capacity),
                )
                return result, bytes(buffer[:result])

            fixed_cases = (
                (3, 2, 0x3F800000),
                (4, 2, 0x00000000),
                (4, 2, 0x80000000),
                (20, 2, 0x33800000),
                (20, 2, 0x4F000000),
                (20, 2, 0x3FA00000),
                (20, 1, 0x3FA147AE),
                (20, 1, 0x3F9EB852),
                (20, 1, 0x411FD70A),
                (20, 0xFFFFFFFF, 0x3FC00000),
                (20, 0xFFFFFFFF, 0x3FB33333),
                (20, 1, 0xC0200000),
                (20, 5, 0x41400000),
                (20, 3, 0x3F000000),
                (6, 10, 0x4145851F),
                (20, 2, 0x7F800000),
                (20, 2, 0x7FC00000),
            )
            for capacity, precision, bits in fixed_cases:
                with self.subTest(
                    capacity=capacity,
                    precision=precision,
                    bits=f"0x{bits:08X}",
                ):
                    self.assertEqual(
                        execute(capacity, precision, bits),
                        reference(capacity, precision, bits),
                    )

            randomizer = random.Random(0x472EF6)
            for _ in range(512):
                bits = randomizer.getrandbits(32)
                capacity = randomizer.randint(12, 64)
                precision = randomizer.choice(
                    (0, 1, 2, 3, 4, 5, 6, 0xFFFFFFFF)
                )
                with self.subTest(
                    random_bits=f"0x{bits:08X}",
                    capacity=capacity,
                    precision=precision,
                ):
                    self.assertEqual(
                        execute(capacity, precision, bits),
                        reference(capacity, precision, bits),
                    )

