    def test_format_extension_source_executes_against_host_oracles(
        self,
    ) -> None:
        sites = {
            item["name"]: item
            for item in self.component_report["overlay"]["patched_sites"]
            if item["name"] in {
                "replace_format_extension_default_encode",
                "replace_format_extension_fields_encode",
            }
        }
        self.assertEqual(
            {
                name: (
                    site["runtime_address"],
                    site["expected_size"],
                    site["expected_sha256"],
                )
                for name, site in sites.items()
            },
            {
                "replace_format_extension_default_encode": (
                    0x00490BC8,
                    48,
                    "24ae700bb0476eb588c1be493887631b64ff769ac087c21c5003f72031bc4d6f",
                ),
                "replace_format_extension_fields_encode": (
                    0x00490BF8,
                    58,
                    "0fb64b8726b7be021654d8fe501065bafa798480ddaabf53df3ad77e6ed8324a",
                ),
            },
        )
        for site in sites.values():
            replacement = bytes.fromhex(site["replacement_hex"])
            self.assertEqual(
                apollo_overlay.decode_thumb_branch(
                    site["runtime_address"],
                    replacement[:4],
                    link=False,
                ),
                site["target_address"],
            )

        base = (
            OPENCFW_ROOT / self.component_report["base"]["path"]
        ).read_bytes()
        application = base[32:]
        run_base = 0x00438000

        def direct_callers(target: int) -> list[int]:
            callers = []
            for offset in range(0, len(application) - 3, 2):
                address = run_base + offset
                try:
                    decoded = apollo_overlay.decode_thumb_branch(
                        address,
                        application[offset:offset + 4],
                        link=True,
                    )
                except apollo_overlay.BuildError:
                    continue
                if decoded == target:
                    callers.append(address)
            return callers

        self.assertEqual(direct_callers(0x00490BC8), [0x00490C20])
        self.assertEqual(direct_callers(0x00490BF8), [0x00490C56])
        error_offset = 32 + 0x00781868 - run_base
        self.assertEqual(
            base[error_offset:error_offset + 18],
            b"invalid extension\x00",
        )

        functions = self.component_report["overlay"]["functions"]
        default_function = functions[
            "open_cfw_format_extension_default_encode"
        ]
        fields_function = functions[
            "open_cfw_format_extension_fields_encode"
        ]
        self.assertEqual(default_function, {"offset": 22480, "size": 52})
        self.assertEqual(fields_function, {"offset": 22532, "size": 50})
        source = (
            COMPONENT_ROOT / "format_extension.c"
        ).read_text()
        self.assertIn("0x004D94D3U", source)
        self.assertIn("0x00781868U", source)

        relocations = self.component_report["overlay"]["link"][
            "resolved_relocations"
        ]

        def relocation_symbols(function: dict[str, int]) -> list[str]:
            return [
                relocation["symbol"]
                for relocation in relocations
                if (
                    function["offset"]
                    <= relocation["site"]
                    < function["offset"] + function["size"]
                )
            ]

        self.assertEqual(
            relocation_symbols(default_function),
            ["open_cfw_format_regular_field_encode"],
        )
        self.assertEqual(
            relocation_symbols(fields_function),
            ["open_cfw_format_extension_default_encode"],
        )

        fixture = (
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "format_extension_host.c"
        )
        with tempfile.TemporaryDirectory() as directory:
            library = Path(directory) / (
                "format_extension.dylib"
                if sys.platform == "darwin"
                else "format_extension.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))
            reset = loaded.open_cfw_test_format_extension_reset
            reset.argtypes = []
            reset.restype = None
            default_encode = (
                loaded.open_cfw_format_extension_default_encode
            )
            default_encode.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            default_encode.restype = ctypes.c_uint
            fields_encode = (
                loaded.open_cfw_format_extension_fields_encode
            )
            fields_encode.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            fields_encode.restype = ctypes.c_uint

            def word(name: str) -> ctypes.c_uint:
                return ctypes.c_uint.in_dll(loaded, name)

            def pointer(name: str) -> ctypes.c_void_p:
                return ctypes.c_void_p.in_dll(loaded, name)

            class Record(ctypes.Structure):
                pass

            Record._fields_ = [
                ("next", ctypes.POINTER(Record)),
                ("custom", ctypes.c_uint),
                ("index", ctypes.c_uint),
            ]
            record_array = Record * 3
            records = record_array.in_dll(
                loaded,
                "open_cfw_test_format_extension_records",
            )
            event_array = ctypes.c_uint * 8
            events = event_array.in_dll(
                loaded,
                "open_cfw_test_format_extension_events",
            )
            output = (ctypes.c_uint * 5)(0, 0, 0, 0, 0)
            field = ctypes.c_void_p(0x33334444)

            reset()
            word(
                "open_cfw_test_format_extension_init_result"
            ).value = 0
            self.assertEqual(default_encode(output, field), 0)
            self.assertEqual(output[4], 0x00781868)
            self.assertEqual(
                word("open_cfw_test_format_extension_init_calls").value,
                1,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_regular_calls").value,
                0,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_error_calls").value,
                1,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_last_error").value,
                0x00781868,
            )
            self.assertEqual(
                pointer(
                    "open_cfw_test_format_extension_init_field"
                ).value,
                field.value,
            )

            reset()
            output[4] = 0xAAAAAAAA
            word(
                "open_cfw_test_format_extension_init_result"
            ).value = 0
            self.assertEqual(default_encode(output, field), 0)
            self.assertEqual(output[4], 0xAAAAAAAA)

            reset()
            output[4] = 0
            word(
                "open_cfw_test_format_extension_regular_result"
            ).value = 0x87654321
            self.assertEqual(
                default_encode(output, field),
                0x87654321,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_init_calls").value,
                1,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_regular_calls").value,
                1,
            )
            self.assertEqual(
                pointer(
                    "open_cfw_test_format_extension_init_iterator"
                ).value,
                pointer(
                    "open_cfw_test_format_extension_last_record"
                ).value,
            )
            self.assertEqual(
                pointer(
                    "open_cfw_test_format_extension_last_output"
                ).value,
                ctypes.addressof(output),
            )
            self.assertEqual(list(events[:2]), [1, 2])

            reset()
            self.assertEqual(fields_encode(output, field), 1)
            self.assertEqual(
                word("open_cfw_test_format_extension_init_calls").value,
                0,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_regular_calls").value,
                0,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_callback_calls").value,
                0,
            )

            def select_first_record(custom: int) -> None:
                pointer(
                    "open_cfw_test_format_extension_head"
                ).value = ctypes.addressof(records[0])
                records[0].next = ctypes.POINTER(Record)()
                records[0].custom = custom

            reset()
            select_first_record(0)
            word(
                "open_cfw_test_format_extension_regular_result"
            ).value = 0x101
            self.assertEqual(fields_encode(output, field), 1)
            self.assertEqual(
                word("open_cfw_test_format_extension_regular_calls").value,
                1,
            )

            reset()
            select_first_record(0)
            word(
                "open_cfw_test_format_extension_regular_result"
            ).value = 0x100
            self.assertEqual(fields_encode(output, field), 0)

            reset()
            select_first_record(1)
            word(
                "open_cfw_test_format_extension_callback_result"
            ).value = 0x101
            self.assertEqual(fields_encode(output, field), 1)
            self.assertEqual(
                word("open_cfw_test_format_extension_callback_calls").value,
                1,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_init_calls").value,
                0,
            )
            self.assertEqual(
                pointer(
                    "open_cfw_test_format_extension_last_output"
                ).value,
                ctypes.addressof(output),
            )
            self.assertEqual(
                pointer(
                    "open_cfw_test_format_extension_last_record"
                ).value,
                ctypes.addressof(records[0]),
            )

            reset()
            select_first_record(1)
            word(
                "open_cfw_test_format_extension_callback_result"
            ).value = 0x100
            self.assertEqual(fields_encode(output, field), 0)

            reset()
            pointer(
                "open_cfw_test_format_extension_head"
            ).value = ctypes.addressof(records[0])
            records[0].custom = 0
            records[1].custom = 1
            records[2].custom = 0
            self.assertEqual(fields_encode(output, field), 1)
            self.assertEqual(
                word("open_cfw_test_format_extension_init_calls").value,
                2,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_regular_calls").value,
                2,
            )
            self.assertEqual(
                word("open_cfw_test_format_extension_callback_calls").value,
                1,
            )
            self.assertEqual(list(events[:5]), [1, 2, 3, 1, 2])

    def test_hash_pinned_patch_site_rejects_stock_span_drift(self) -> None:
        config = apollo_overlay.load_config(COMPONENT_ROOT / "overlay.json")
        config = json.loads(json.dumps(config))
        site = next(
            item
            for item in config["patch_sites"]
            if item["name"] == "replace_ui_display_initializer"
        )
        site["expected_sha256"] = "0" * 64
        base = (
            OPENCFW_ROOT / config["base"]["path"]
        ).read_bytes()
        overlay = (
            OPENCFW_ROOT
            / self.component_report["overlay"]["artifact"]
        ).read_bytes()

        with self.assertRaisesRegex(
            apollo_overlay.BuildError,
            "replace_ui_display_initializer.*found",
        ):
            apollo_overlay.patch_component(
                base=base,
                overlay=overlay,
                functions=self.component_report["overlay"]["functions"],
                config=config,
            )

    def test_multi_module_linker_resolves_internal_call_and_rodata(self) -> None:
        fixture = OPENCFW_ROOT / "tests" / "fixtures" / "linker_probe.c"
        config = {
            "toolchain": {
                "target": "thumbv7em-none-eabi",
                "reviewed_version": (
                    "Apple clang version 21.0.0 (clang-2100.3.30.1)"
                ),
                "flags": [
                    "-mthumb",
                    "-O2",
                    "-ffreestanding",
                    "-fno-builtin",
                    "-fno-unwind-tables",
                    "-fno-asynchronous-unwind-tables",
                    "-fropi",
                    "-Wall",
                    "-Wextra",
                    "-Werror",
                ],
            },
            "functions": [
                "open_cfw_probe_inner",
                "open_cfw_probe_outer",
            ],
        }
        with tempfile.TemporaryDirectory() as directory:
            overlay, functions, _version, link = apollo_overlay.compile_overlay(
                clang=os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                source_path=fixture,
                object_path=Path(directory) / "linker_probe.o",
                config=config,
            )
        self.assertGreater(len(overlay), 0)
        self.assertEqual(set(functions), set(config["functions"]))
        self.assertEqual(link["rodata_size"], 4)
        self.assertGreaterEqual(link["resolved_relocation_count"], 3)
        self.assertEqual(
            {
                relocation["type"]
                for relocation in link["resolved_relocations"]
            },
            {
                apollo_overlay.R_ARM_THM_JUMP24,
                apollo_overlay.R_ARM_THM_MOVW_PREL_NC,
                apollo_overlay.R_ARM_THM_MOVT_PREL,
            },
        )

    def test_mini_linker_rejects_external_calls_and_implicit_state(self) -> None:
        toolchain = {
            "target": "thumbv7em-none-eabi",
            "reviewed_version": (
                "Apple clang version 21.0.0 (clang-2100.3.30.1)"
            ),
            "flags": [
                "-mthumb",
                "-O2",
                "-ffreestanding",
                "-fno-builtin",
                "-fno-unwind-tables",
                "-fno-asynchronous-unwind-tables",
                "-fropi",
                "-Wall",
                "-Wextra",
                "-Werror",
            ],
        }
        fixture_root = OPENCFW_ROOT / "tests" / "fixtures"
        cases = [
            (
                "linker_external_probe.c",
                ["open_cfw_external_probe"],
                "unresolvable relocation",
            ),
            (
                "linker_writable_probe.c",
                ["open_cfw_writable_probe"],
                "writable section",
            ),
        ]
        with tempfile.TemporaryDirectory() as directory:
            for index, (name, functions, message) in enumerate(cases):
                with self.subTest(name=name):
                    with self.assertRaisesRegex(
                        apollo_overlay.BuildError,
                        message,
                    ):
                        apollo_overlay.compile_overlay(
                            clang=os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                            source_path=fixture_root / name,
                            object_path=Path(directory) / f"negative-{index}.o",
                            config={
                                "toolchain": toolchain,
                                "functions": functions,
                            },
                        )

    def test_lens_side_policy_executes_against_host_oracles(self) -> None:
        source = COMPONENT_ROOT / "lens_side_policy.c"
        with tempfile.TemporaryDirectory() as directory:
            library = Path(directory) / (
                "lens_side_policy.dylib"
                if sys.platform == "darwin"
                else "lens_side_policy.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(source),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))
            classify = loaded.open_cfw_classify_lens_samples
            classify.argtypes = [ctypes.POINTER(ctypes.c_uint)]
            classify.restype = ctypes.c_uint

            def observed(values: list[int]) -> int:
                samples = (ctypes.c_uint * 5)(*values)
                return int(classify(samples))

            self.assertEqual(observed([1, 1, 1, 1, 1]), 2)
            for value in (0, 2, 7, 0xFFFFFFFF):
                self.assertEqual(observed([value] * 5), 1)
            for index in range(1, 5):
                values = [1] * 5
                values[index] = 2
                self.assertEqual(observed(values), 3)

    def test_evenhub_lifecycle_source_executes_against_host_state(self) -> None:
        source = COMPONENT_ROOT / "evenhub_lifecycle.c"
        with tempfile.TemporaryDirectory() as directory:
            temporary = Path(directory)
            wrapper = temporary / "evenhub_lifecycle_host.c"
            wrapper.write_text(
                "\n".join(
                    [
                        "volatile unsigned int open_cfw_test_active;",
                        "volatile unsigned int open_cfw_test_state;",
                        "volatile unsigned int open_cfw_test_keepalive;",
                        "volatile unsigned char open_cfw_test_shutdown;",
                        "volatile unsigned int open_cfw_test_imu_enabled;",
                        "volatile unsigned int open_cfw_test_imu_status;",
                        "unsigned int open_cfw_test_start_count;",
                        "unsigned int open_cfw_test_stop_count;",
                        "unsigned int open_cfw_test_start_frequency;",
                        "unsigned int open_cfw_test_stop_frequency;",
                        "void open_cfw_test_imu_start(unsigned int value) {",
                        "    ++open_cfw_test_start_count;",
                        "    open_cfw_test_start_frequency = value;",
                        "}",
                        "void open_cfw_test_imu_stop(unsigned int value) {",
                        "    ++open_cfw_test_stop_count;",
                        "    open_cfw_test_stop_frequency = value;",
                        "}",
                        "#define OPEN_CFW_EVENHUB_ACTIVE_WORD open_cfw_test_active",
                        "#define OPEN_CFW_EVENHUB_STATE_WORD open_cfw_test_state",
                        "#define OPEN_CFW_EVENHUB_KEEPALIVE_WORD open_cfw_test_keepalive",
                        "#define OPEN_CFW_EVENHUB_SHUTDOWN_BYTE open_cfw_test_shutdown",
                        "#define OPEN_CFW_EVENHUB_IMU_ENABLED_WORD open_cfw_test_imu_enabled",
                        "#define OPEN_CFW_EVENHUB_IMU_STATUS_WORD open_cfw_test_imu_status",
                        "#define OPEN_CFW_EVENHUB_IMU_START(value) open_cfw_test_imu_start(value)",
                        "#define OPEN_CFW_EVENHUB_IMU_STOP(value) open_cfw_test_imu_stop(value)",
                        f"#include {json.dumps(str(source))}",
                        "",
                    ]
                ),
                encoding="utf-8",
            )
            library = temporary / (
                "evenhub_lifecycle.dylib"
                if sys.platform == "darwin"
                else "evenhub_lifecycle.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(wrapper),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))

            active_mark = loaded.open_cfw_evenhub_active_mark
            active_mark.argtypes = []
            active_mark.restype = None
            state_get = loaded.open_cfw_evenhub_state_get
            state_get.argtypes = []
            state_get.restype = ctypes.c_uint
            state_set = loaded.open_cfw_evenhub_state_set
            state_set.argtypes = [ctypes.c_uint]
            state_set.restype = None
            keepalive_reset = loaded.open_cfw_evenhub_keepalive_reset
            keepalive_reset.argtypes = []
            keepalive_reset.restype = None
            shutdown_mark = loaded.open_cfw_evenhub_shutdown_mark
            shutdown_mark.argtypes = []
            shutdown_mark.restype = None
            imu_enable = loaded.open_cfw_evenhub_imu_enable
            imu_enable.argtypes = [ctypes.c_uint]
            imu_enable.restype = ctypes.c_uint

            active = ctypes.c_uint.in_dll(loaded, "open_cfw_test_active")
            state = ctypes.c_uint.in_dll(loaded, "open_cfw_test_state")
            keepalive = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_keepalive",
            )
            shutdown = ctypes.c_ubyte.in_dll(
                loaded,
                "open_cfw_test_shutdown",
            )
            imu_enabled = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_imu_enabled",
            )
            imu_status = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_imu_status",
            )
            start_count = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_start_count",
            )
            stop_count = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_stop_count",
            )
            start_frequency = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_start_frequency",
            )
            stop_frequency = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_stop_frequency",
            )

            active.value = 0
            active_mark()
            self.assertEqual(active.value, 1)

            state_set(0xDEADBEEF)
            self.assertEqual(state.value, 0xDEADBEEF)
            self.assertEqual(state_get(), 0xDEADBEEF)

            keepalive.value = 0xFFFFFFFF
            keepalive_reset()
            self.assertEqual(keepalive.value, 0)

            shutdown.value = 0
            shutdown_mark()
            self.assertEqual(shutdown.value, 1)

            imu_status.value = 0x12345678
            imu_enabled.value = 0
            self.assertEqual(imu_enable(1), 0x12345678)
            self.assertEqual(imu_enabled.value, 1)
            self.assertEqual(start_count.value, 1)
            self.assertEqual(start_frequency.value, 5)
            self.assertEqual(imu_enable(1), 0x12345678)
            self.assertEqual(start_count.value, 1)

            self.assertEqual(imu_enable(2), 0x12345678)
            self.assertEqual(start_count.value, 1)
            self.assertEqual(stop_count.value, 0)

            imu_enabled.value = 2
            self.assertEqual(imu_enable(0), 0x12345678)
            self.assertEqual(imu_enabled.value, 2)
            self.assertEqual(stop_count.value, 0)

            imu_enabled.value = 1
            self.assertEqual(imu_enable(0), 0x12345678)
            self.assertEqual(imu_enabled.value, 0)
            self.assertEqual(stop_count.value, 1)
            self.assertEqual(stop_frequency.value, 5)
            self.assertEqual(imu_enable(0), 0x12345678)
            self.assertEqual(stop_count.value, 1)

