    def test_ui_startup_app_source_executes_against_host_oracles(
        self,
    ) -> None:
        fixture = (
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "ui_startup_app_host.c"
        )
        with tempfile.TemporaryDirectory() as directory:
            temporary = Path(directory)
            library = temporary / (
                "ui_startup_app.dylib"
                if sys.platform == "darwin"
                else "ui_startup_app.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))

            startup_app = loaded.open_cfw_ui_startup_app_id
            startup_app.argtypes = [ctypes.c_uint, ctypes.c_uint]
            startup_app.restype = ctypes.c_uint

            def word(name: str) -> ctypes.c_uint:
                return ctypes.c_uint.in_dll(loaded, name)

            policy_count = word("open_cfw_test_policy_count")
            policy_ready = word("open_cfw_test_policy_ready")
            policy_operation = word("open_cfw_test_policy_operation")
            policy_result = word("open_cfw_test_policy_result")
            log_flags = word("open_cfw_test_log_flags_value")
            log_count = word("open_cfw_test_log_count")
            trace_count = word("open_cfw_test_trace_count")
            log_levels = (ctypes.c_uint * 2).in_dll(
                loaded,
                "open_cfw_test_log_level",
            )
            log_lines = (ctypes.c_uint * 2).in_dll(
                loaded,
                "open_cfw_test_log_line",
            )
            log_tags = (ctypes.c_ulong * 2).in_dll(
                loaded,
                "open_cfw_test_log_tag",
            )
            log_formats = (ctypes.c_ulong * 2).in_dll(
                loaded,
                "open_cfw_test_log_format",
            )
            trace_masks = (ctypes.c_uint * 2).in_dll(
                loaded,
                "open_cfw_test_trace_mask",
            )
            trace_schemas = (ctypes.c_ulong * 2).in_dll(
                loaded,
                "open_cfw_test_trace_schema",
            )

            for input_type in (2, 3, 5, 0xFFFFFFFF):
                with self.subTest(invalid_input_type=input_type):
                    policy_count.value = 0
                    self.assertEqual(startup_app(1, input_type), 0)
                    self.assertEqual(policy_count.value, 0)

            for input_type, operation in ((0, 0), (1, 1), (4, 2)):
                with self.subTest(input_type=input_type):
                    policy_count.value = 0
                    policy_result.value = 0
                    self.assertEqual(
                        startup_app(0x101, input_type),
                        0,
                    )
                    self.assertEqual(policy_count.value, 1)
                    self.assertEqual(policy_ready.value, 1)
                    self.assertEqual(policy_operation.value, operation)

            policy_result.value = 0x101
            self.assertEqual(startup_app(0x100, 4), 3)
            self.assertEqual(policy_ready.value, 0)
            self.assertEqual(policy_operation.value, 2)

            log_count.value = 0
            trace_count.value = 0
            log_flags.value = 2
            policy_result.value = 2
            self.assertEqual(startup_app(1, 1), 0)
            self.assertEqual(log_count.value, 2)
            self.assertEqual(list(log_levels), [2, 4])
            self.assertEqual(list(log_lines), [0x156, 0x15C])
            self.assertEqual(
                list(log_tags),
                [0x00785AC0, 0x00785AC0],
            )
            self.assertEqual(
                list(log_formats),
                [0x0077ED5C, 0x006E7534],
            )

            log_count.value = 0
            trace_count.value = 0
            log_flags.value = 1
            self.assertEqual(startup_app(1, 4), 0)
            self.assertEqual(log_count.value, 0)
            self.assertEqual(trace_count.value, 2)
            self.assertEqual(
                list(trace_masks),
                [0x08400000, 0x11400000],
            )
            self.assertEqual(
                list(trace_schemas),
                [0x007535DC, 0x006DA6D8],
            )

            log_count.value = 0
            trace_count.value = 0
            log_flags.value = 2
            policy_result.value = 0
            self.assertEqual(startup_app(1, 0), 0)
            self.assertEqual(log_count.value, 1)
            self.assertEqual(log_levels[0], 4)
            self.assertEqual(log_lines[0], 0x15C)
            self.assertEqual(trace_count.value, 0)

    def test_ui_onboarding_gate_source_executes_against_host_oracles(
        self,
    ) -> None:
        fixture = (
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "ui_onboarding_gate_host.c"
        )
        with tempfile.TemporaryDirectory() as directory:
            temporary = Path(directory)
            library = temporary / (
                "ui_onboarding_gate.dylib"
                if sys.platform == "darwin"
                else "ui_onboarding_gate.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))

            onboarding_running = loaded.open_cfw_ui_onboarding_running
            onboarding_running.argtypes = []
            onboarding_running.restype = ctypes.c_uint
            results = (ctypes.c_uint * 3).in_dll(
                loaded,
                "open_cfw_test_onboarding_result",
            )
            counts = (ctypes.c_uint * 3).in_dll(
                loaded,
                "open_cfw_test_onboarding_count",
            )
            order = (ctypes.c_uint * 3).in_dll(
                loaded,
                "open_cfw_test_onboarding_order",
            )
            order_count = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_onboarding_order_count",
            )

            def execute(
                values: tuple[int, int, int],
            ) -> tuple[int, list[int], list[int]]:
                for index, value in enumerate(values):
                    results[index] = value
                    counts[index] = 0
                    order[index] = 0xFFFFFFFF
                order_count.value = 0
                observed = onboarding_running()
                return (
                    observed,
                    list(counts),
                    list(order)[:order_count.value],
                )

            self.assertEqual(
                execute((1, 1, 1)),
                (1, [1, 0, 0], [0]),
            )
            self.assertEqual(
                execute((2, 1, 1)),
                (1, [1, 1, 0], [0, 1]),
            )
            self.assertEqual(
                execute((0, 0xFFFFFFFF, 1)),
                (1, [1, 1, 1], [0, 1, 2]),
            )
            self.assertEqual(
                execute((0, 0, 0)),
                (0, [1, 1, 1], [0, 1, 2]),
            )
            self.assertEqual(
                execute((2, 3, 0xFFFFFFFF)),
                (0, [1, 1, 1], [0, 1, 2]),
            )

    def test_ui_input_event_source_executes_against_host_oracles(
        self,
    ) -> None:
        fixture = (
            OPENCFW_ROOT
            / "tests"
            / "fixtures"
            / "ui_input_event_host.c"
        )
        with tempfile.TemporaryDirectory() as directory:
            temporary = Path(directory)
            library = temporary / (
                "ui_input_event.dylib"
                if sys.platform == "darwin"
                else "ui_input_event.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(fixture),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))

            input_event = loaded.open_cfw_ui_input_event_handler
            input_event.argtypes = [ctypes.POINTER(ctypes.c_ubyte)]
            input_event.restype = ctypes.c_uint

            def word(name: str) -> ctypes.c_uint:
                return ctypes.c_uint.in_dll(loaded, name)

            state_words = (ctypes.c_uint * 4).in_dll(
                loaded,
                "open_cfw_test_state",
            )
            state_bytes = (ctypes.c_ubyte * 16).in_dll(
                loaded,
                "open_cfw_test_state",
            )
            post_events = (ctypes.c_uint * 8).in_dll(
                loaded,
                "open_cfw_test_post_event",
            )
            post_data = (ctypes.c_ulong * 8).in_dll(
                loaded,
                "open_cfw_test_post_data",
            )
            post_values = (ctypes.c_uint * 8).in_dll(
                loaded,
                "open_cfw_test_post_value",
            )
            system_args = (ctypes.c_uint * 4).in_dll(
                loaded,
                "open_cfw_test_system_args",
            )
            dispatch_args = (ctypes.c_uint * 4).in_dll(
                loaded,
                "open_cfw_test_dispatch_args",
            )
            ring_coordinates = (ctypes.c_int * 2).in_dll(
                loaded,
                "open_cfw_test_ring_coordinates",
            )
            log_levels = (ctypes.c_uint * 8).in_dll(
                loaded,
                "open_cfw_test_log_level",
            )
            log_lines = (ctypes.c_uint * 8).in_dll(
                loaded,
                "open_cfw_test_log_line",
            )
            log_formats = (ctypes.c_ulong * 8).in_dll(
                loaded,
                "open_cfw_test_log_format",
            )
            trace_masks = (ctypes.c_uint * 8).in_dll(
                loaded,
                "open_cfw_test_trace_mask",
            )
            trace_schemas = (ctypes.c_ulong * 8).in_dll(
                loaded,
                "open_cfw_test_trace_schema",
            )
            scalar_names = (
                "open_cfw_test_post_result",
                "open_cfw_test_post_count",
                "open_cfw_test_onboarding_result",
                "open_cfw_test_onboarding_count",
                "open_cfw_test_terminal_result",
                "open_cfw_test_terminal_count",
                "open_cfw_test_longpress_count",
                "open_cfw_test_lens_result",
                "open_cfw_test_lens_count",
                "open_cfw_test_system_count",
                "open_cfw_test_mode3_reset_count",
                "open_cfw_test_mode_handle_result",
                "open_cfw_test_mode_handle_count",
                "open_cfw_test_mode_active_result",
                "open_cfw_test_mode_active_count",
                "open_cfw_test_dispatch_count",
                "open_cfw_test_ring_count",
                "open_cfw_test_x_value",
                "open_cfw_test_x_set_count",
                "open_cfw_test_x_apply_count",
                "open_cfw_test_y_value",
                "open_cfw_test_y_set_count",
                "open_cfw_test_y_apply_count",
                "open_cfw_test_log_flags_value",
                "open_cfw_test_log_count",
                "open_cfw_test_trace_count",
            )

            def reset(
                application_id: int = 1,
                display_mode: int = 0,
            ) -> None:
                for name in scalar_names:
                    word(name).value = 0
                word("open_cfw_test_state_present").value = 1
                word("open_cfw_test_stage").value = 0
                word("open_cfw_test_current_service").value = 0xA5
                for index in range(4):
                    state_words[index] = 0
                state_words[0] = application_id
                state_bytes[11] = display_mode

            def execute(
                event_id: int,
                event_value: int = 0xBEEF,
                payload: int = 0x76543210,
            ) -> int:
                encoded = struct.pack(
                    "<HII",
                    event_value & 0xFFFF,
                    event_id & 0xFFFFFFFF,
                    payload & 0xFFFFFFFF,
                )
                record = (ctypes.c_ubyte * len(encoded)).from_buffer_copy(
                    encoded
                )
                return input_event(record)

            simple_events = (
                (0, 0x0A, 0xBEEF),
                (1, 0x48, 0xBEEF),
                (2, 0x3F, 0x76543210),
                (7, 0x49, 0x76543210),
                (8, 0x40, 0x76543210),
                (9, 0x41, 0x76543210),
                (15, 0x4F, 0x76543210),
                (16, 0x50, 0x76543210),
            )
            for event_id, post_event, posted_value in simple_events:
                with self.subTest(simple_event=event_id):
                    reset()
                    self.assertEqual(execute(event_id), 0)
                    self.assertEqual(word("open_cfw_test_post_count").value, 1)
                    self.assertEqual(post_events[0], post_event)
                    self.assertEqual(post_values[0], posted_value)

            for event_id, post_event in ((4, 0x44), (5, 0x45)):
                with self.subTest(coordinate_event=event_id):
                    reset()
                    self.assertEqual(execute(event_id, payload=0x8001FFFE), 0)
                    self.assertEqual(post_events[0], post_event)
                    self.assertEqual(post_values[0], 0xFFFFFFFE)

            reset()
            self.assertEqual(execute(14, payload=0x8001FFFE), 0)
            self.assertEqual(word("open_cfw_test_ring_count").value, 1)
            self.assertEqual(word("open_cfw_test_ring_event").value, 0x4A)
            self.assertEqual(list(ring_coordinates), [-2, -32767])
            self.assertEqual(word("open_cfw_test_post_count").value, 0)

            reset()
            self.assertEqual(execute(6), 0)
            self.assertEqual(word("open_cfw_test_post_count").value, 0)
            self.assertEqual(word("open_cfw_test_onboarding_count").value, 1)
            reset()
            word("open_cfw_test_onboarding_result").value = 1
            self.assertEqual(execute(6), 0)
            self.assertEqual(post_events[0], 0x4B)
            self.assertEqual(post_values[0], 0x76543210)

            reset()
            self.assertEqual(execute(10), 0)
            self.assertEqual(word("open_cfw_test_post_count").value, 0)
            reset()
            self.assertEqual(execute(13), 0)
            self.assertEqual(word("open_cfw_test_post_count").value, 0)
            self.assertEqual(word("open_cfw_test_log_count").value, 0)

            reset()
            self.assertEqual(execute(11, payload=0x89ABCDEF), 0)
            self.assertEqual(word("open_cfw_test_y_set_count").value, 1)
            self.assertEqual(word("open_cfw_test_y_value").value, 0x89ABCDEF)
            self.assertEqual(word("open_cfw_test_y_apply_count").value, 1)
            reset()
            self.assertEqual(execute(12, payload=0x10203040), 0)
            self.assertEqual(word("open_cfw_test_x_set_count").value, 1)
            self.assertEqual(word("open_cfw_test_x_value").value, 0x10203040)
            self.assertEqual(word("open_cfw_test_x_apply_count").value, 1)

            reset()
            word("open_cfw_test_state_present").value = 0
            word("open_cfw_test_log_flags_value").value = 3
            self.assertEqual(execute(0), 0xFFFFFFFF)
            self.assertEqual(list(log_levels)[:1], [2])
            self.assertEqual(list(log_lines)[:1], [0x177])
            self.assertEqual(list(log_formats)[:1], [0x00753600])
            self.assertEqual(list(trace_masks)[:1], [0x08000000])
            self.assertEqual(list(trace_schemas)[:1], [0x0072895C])

            reset()
            word("open_cfw_test_log_flags_value").value = 3
            self.assertEqual(execute(17), 0)
            self.assertEqual(list(log_levels)[:1], [2])
            self.assertEqual(list(log_lines)[:1], [0x20B])
            self.assertEqual(list(log_formats)[:1], [0x0076AD90])
            self.assertEqual(list(trace_masks)[:1], [0x08400000])
            self.assertEqual(list(trace_schemas)[:1], [0x0073DDF4])

            reset(application_id=0xE0, display_mode=0)
            self.assertEqual(execute(3), 0)
            self.assertEqual(word("open_cfw_test_longpress_count").value, 1)
            self.assertEqual(word("open_cfw_test_lens_count").value, 0)

            reset(application_id=7, display_mode=0)
            word("open_cfw_test_lens_result").value = 1
            self.assertEqual(execute(3), 0)
            self.assertEqual(word("open_cfw_test_system_count").value, 1)
            self.assertEqual(list(system_args), [3, 0, 0, 0])

            reset(application_id=0x30, display_mode=0)
            word("open_cfw_test_terminal_result").value = 1
            self.assertEqual(execute(3), 0)
            self.assertEqual(post_events[0], 8)
            self.assertEqual(post_values[0], 0x76543210)

            reset(application_id=7, display_mode=0)
            word("open_cfw_test_onboarding_result").value = 1
            self.assertEqual(execute(3), 0)
            self.assertEqual(post_events[0], 8)
            self.assertEqual(word("open_cfw_test_terminal_count").value, 0)

            reset(application_id=3, display_mode=1)
            word("open_cfw_test_stage").value = 2
            self.assertEqual(execute(3), 1)
            self.assertEqual(word("open_cfw_test_mode3_reset_count").value, 1)
            self.assertEqual(post_events[0], 0)
            self.assertEqual(post_data[0], 3)
            self.assertEqual(
                word("open_cfw_test_current_service").value,
                0xA5,
            )

            reset(application_id=3, display_mode=1)
            self.assertEqual(execute(3), 0)
            self.assertEqual(word("open_cfw_test_current_service").value, 0)

            reset(application_id=8, display_mode=1)
            word("open_cfw_test_mode_handle_result").value = 0xCAFE
            word("open_cfw_test_mode_active_result").value = 1
            word("open_cfw_test_post_result").value = 1
            self.assertEqual(execute(3), 0)
            self.assertEqual(word("open_cfw_test_mode_handle_count").value, 2)
            self.assertEqual(word("open_cfw_test_mode_active_count").value, 2)
            self.assertEqual(word("open_cfw_test_dispatch_count").value, 1)
            self.assertEqual(list(dispatch_args), [8, 5, 0, 0])
            self.assertEqual(word("open_cfw_test_current_service").value, 3)

