            reset()
            word("open_cfw_test_forced_state").value = 1
            word("open_cfw_test_background").value = 0x31
            word("open_cfw_test_foreground").value = 0x41
            word("open_cfw_test_input_result").value = 1
            set_message(7, 0, 0)
            display_thread(None)
            self.assertEqual(list(dispatch_service)[:1], [0x41])
            self.assertEqual(list(dispatch_event)[:1], [5])
