                        ") {",
                        "    unsigned int index; const unsigned char *bytes=data;",
                        "    ++test_raw_count; test_raw_args[0]=device; test_raw_args[1]=count;",
                        "    test_raw_args[2]=offset; test_raw_args[3]=length;",
                        "    for (index=0; index<5; ++index) test_raw_data[index]=bytes[index];",
                        "}",
                        "void test_cleanup(unsigned int a0, unsigned int a1) {",
                        "    (void)a0; (void)a1; ++test_cleanup_count;",
                        "}",
