                        "    ++test_state_report_count; test_state_report_value=value;",
                        "}",
                        "void test_destroy(void *manager) { (void)manager; ++test_destroy_count; }",
                        "void test_free(void *manager) { (void)manager; ++test_free_count; }",
                        "void test_enqueue(void *endpoint, unsigned int type, const unsigned int *event) {",
                        "    ++test_enqueue_count; test_enqueue_endpoint=endpoint;",
