                        "    ++test_log_count; test_log_level=level; test_log_line=line;",
                        "}",
                        "void test_trace_record(",
                        "    unsigned int mask, const void *schema, const void *format, ...",
                        ") {",
                        "    (void)schema;(void)format; ++test_trace_count; test_trace_mask=mask;",
                        "}",
                        "#define OPEN_CFW_EVENHUB_UI_IMU_ENABLED test_imu_enabled",
                        "#define OPEN_CFW_EVENHUB_UI_START_TICK test_start_tick",
                        "#define OPEN_CFW_EVENHUB_UI_DISPLAY_FLAG test_display_flag",
                        "#define OPEN_CFW_EVENHUB_UI_STATE test_state",
                        "#define OPEN_CFW_EVENHUB_UI_NAVIGATION test_navigation",
                        "#define OPEN_CFW_EVENHUB_UI_ACTIVE test_active",
                        "#define OPEN_CFW_EVENHUB_UI_MANAGER test_manager",
                        "#define OPEN_CFW_EVENHUB_UI_STARTED test_started",
                        "#define OPEN_CFW_EVENHUB_UI_KEEPALIVE_COUNT test_keepalive",
                        "#define OPEN_CFW_EVENHUB_UI_SECOND_COUNT test_second_count",
                        "#define OPEN_CFW_EVENHUB_UI_SECOND_FLAG test_second_flag",
                        "#define OPEN_CFW_EVENHUB_UI_REGISTRY_ROOT test_registry_root",
                        "#define OPEN_CFW_EVENHUB_UI_TIMER() test_timer()",
                        "#define OPEN_CFW_EVENHUB_UI_INITIALIZE() test_initialize()",
                        "#define OPEN_CFW_EVENHUB_UI_ALLOCATE(size) test_allocate(size)",
                        "#define OPEN_CFW_EVENHUB_UI_CLEAR(dest,size,value) test_clear(dest,size,value)",
                        "#define OPEN_CFW_EVENHUB_UI_CREATE_ROOT(context) test_create_root(context)",
                        "#define OPEN_CFW_EVENHUB_UI_CREATE_DISPLAY(a1,a2,mgr) test_create_display(a1,a2,mgr)",
                        "#define OPEN_CFW_EVENHUB_UI_SHOW(root) test_show(root)",
                        "#define OPEN_CFW_EVENHUB_UI_ROUTE(mgr,a1,a2) test_route(mgr,a1,a2)",
                        "#define OPEN_CFW_EVENHUB_UI_DRIVER(op,arg) test_driver(op,arg)",
                        "#define OPEN_CFW_EVENHUB_UI_SEND_STATUS(a0,a1,a2,a3,a4,a5) test_status(a0,a1,a2,a3,a4,a5)",
                        "#define OPEN_CFW_EVENHUB_UI_REQUEST_DISPLAY_STOP(a0,a1,a2,a3) test_stop(a0,a1,a2,a3)",
                        "#define OPEN_CFW_EVENHUB_UI_SEND_RAW(a0,a1,a2,a3,a4) test_raw(a0,a1,a2,a3,a4)",
                        "#define OPEN_CFW_EVENHUB_UI_DISPLAY_CLEANUP(a0,a1) test_cleanup(a0,a1)",
