            raw_data = (ctypes.c_ubyte * 5).in_dll(
                loaded,
                "test_raw_data",
            )
            route_count = word("test_route_count")
            route_arg1 = word("test_route_arg1")
            route_arg2 = word("test_route_arg2")
            driver_count = word("test_driver_count")
            driver_op = word("test_driver_op")
