    def test_evenhub_decompression_source_executes_against_host_oracles(
        self,
    ) -> None:
        source = COMPONENT_ROOT / "evenhub_decompression.c"
        with tempfile.TemporaryDirectory() as directory:
            temporary = Path(directory)
            wrapper = temporary / "evenhub_decompression_host.c"
            wrapper.write_text(
                "\n".join(
                    [
                        "int open_cfw_test_mode2_result;",
                        "unsigned int open_cfw_test_mode2_calls;",
                        "unsigned int open_cfw_test_mode2_input_length;",
                        "unsigned int open_cfw_test_mode2_output_capacity;",
                        "unsigned int open_cfw_test_mode2_input_head;",
                        "int open_cfw_test_mode2_decode(",
                        "    const unsigned char *input,",
                        "    unsigned char *output,",
                        "    unsigned int input_length,",
                        "    unsigned int output_capacity",
                        ") {",
                        "    ++open_cfw_test_mode2_calls;",
                        "    open_cfw_test_mode2_input_length = input_length;",
                        "    open_cfw_test_mode2_output_capacity = output_capacity;",
                        "    open_cfw_test_mode2_input_head = input[0];",
                        "    output[0] = 0xA5;",
                        "    return open_cfw_test_mode2_result;",
                        "}",
                        "#define OPEN_CFW_EVENHUB_MODE2_DECODE(input, output, input_length, output_capacity) \\",
                        "    open_cfw_test_mode2_decode(input, output, input_length, output_capacity)",
                        f"#include {json.dumps(str(source))}",
                        "",
                    ]
                ),
                encoding="utf-8",
            )
            library = temporary / (
                "evenhub_decompression.dylib"
                if sys.platform == "darwin"
                else "evenhub_decompression.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(wrapper),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))

            byte_pointer = ctypes.POINTER(ctypes.c_ubyte)
            mode2 = loaded.open_cfw_evenhub_mode2_decompress_legacy
            mode2.argtypes = [
                byte_pointer,
                ctypes.c_uint,
                byte_pointer,
                ctypes.c_uint,
            ]
            mode2.restype = ctypes.c_uint
            rle_decode = loaded.open_cfw_evenhub_rle_decode
            rle_decode.argtypes = list(mode2.argtypes)
            rle_decode.restype = ctypes.c_uint
            rle_wrapper = loaded.open_cfw_evenhub_rle_decompress
            rle_wrapper.argtypes = list(mode2.argtypes)
            rle_wrapper.restype = ctypes.c_uint

            mode2_result = ctypes.c_int.in_dll(
                loaded,
                "open_cfw_test_mode2_result",
            )
            mode2_calls = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_mode2_calls",
            )
            mode2_input_length = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_mode2_input_length",
            )
            mode2_output_capacity = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_mode2_output_capacity",
            )
            mode2_input_head = ctypes.c_uint.in_dll(
                loaded,
                "open_cfw_test_mode2_input_head",
            )
            input_buffer = (ctypes.c_ubyte * 3)(0x12, 0x34, 0x56)
            output_buffer = (ctypes.c_ubyte * 8)(*[0xCC] * 8)

            self.assertEqual(mode2(None, 3, output_buffer, 8), 0)
            self.assertEqual(mode2(input_buffer, 0, output_buffer, 8), 0)
            self.assertEqual(mode2(input_buffer, 3, None, 8), 0)
            self.assertEqual(mode2(input_buffer, 3, output_buffer, 0), 0)
            self.assertEqual(mode2_calls.value, 0)

            for stock_result, expected in ((-7, 0), (0, 0), (1, 1), (42, 42)):
                mode2_result.value = stock_result
                output_buffer[0] = 0xCC
                self.assertEqual(mode2(input_buffer, 3, output_buffer, 8), expected)
                self.assertEqual(output_buffer[0], 0xA5)
                self.assertEqual(mode2_input_length.value, 3)
                self.assertEqual(mode2_output_capacity.value, 8)
                self.assertEqual(mode2_input_head.value, 0x12)
            self.assertEqual(mode2_calls.value, 4)

            def reference(data: list[int], capacity: int) -> tuple[int, list[int]]:
                input_offset = 0
                output: list[int] = []
                if not data or capacity == 0:
                    return 0, output
                while input_offset < len(data):
                    if input_offset + 1 >= len(data):
                        return len(output), output
                    count = data[input_offset]
                    value = data[input_offset + 1]
                    input_offset += 2
                    if capacity < len(output) + count:
                        output.extend([value] * (capacity - len(output)))
                        return len(output), output
                    output.extend([value] * count)
                return len(output), output

            def execute(
                function: ctypes._CFuncPtr,
                data: list[int],
                capacity: int,
            ) -> tuple[int, list[int], list[int]]:
                input_array = (ctypes.c_ubyte * max(1, len(data)))(
                    *(data or [0])
                )
                output_array = (ctypes.c_ubyte * max(1, capacity + 4))(
                    *([0xCC] * max(1, capacity + 4))
                )
                observed = int(
                    function(
                        input_array,
                        len(data),
                        output_array,
                        capacity,
                    )
                )
                return (
                    observed,
                    list(output_array[:observed]),
                    list(output_array[capacity:capacity + 4]),
                )

            cases = [
                ([], 8),
                ([3], 8),
                ([3, 0x41], 8),
                ([0, 0x41, 2, 0x42], 8),
                ([3, 0x41, 2, 0x42], 5),
                ([3, 0x41, 2, 0x42], 4),
                ([255, 0x7E], 256),
            ]
            generator = random.Random(0xE0C0DE)
            for _ in range(128):
                cases.append(
                    (
                        [
                            generator.randrange(0, 16)
                            if index % 2 == 0
                            else generator.randrange(0, 256)
                            for index in range(generator.randrange(0, 20))
                        ],
                        generator.randrange(0, 64),
                    )
                )

            for data, capacity in cases:
                expected_length, expected_output = reference(data, capacity)
                for function in (rle_decode, rle_wrapper):
                    with self.subTest(
                        function=function.__name__,
                        data=data,
                        capacity=capacity,
                    ):
                        observed_length, observed_output, guard = execute(
                            function,
                            data,
                            capacity,
                        )
                        self.assertEqual(observed_length, expected_length)
                        self.assertEqual(observed_output, expected_output)
                        self.assertEqual(guard, [0xCC] * len(guard))

            self.assertEqual(rle_decode(None, 2, output_buffer, 8), 0)
            self.assertEqual(rle_decode(input_buffer, 2, None, 8), 0)

    def test_evenhub_lz4_source_executes_against_block_oracles(self) -> None:
        lz4_source = COMPONENT_ROOT / "evenhub_lz4.c"
        adapter_source = COMPONENT_ROOT / "evenhub_decompression.c"
        with tempfile.TemporaryDirectory() as directory:
            temporary = Path(directory)
            library = temporary / (
                "evenhub_lz4.dylib"
                if sys.platform == "darwin"
                else "evenhub_lz4.so"
            )
            command = [
                os.environ.get("OPENCFW_CLANG", "/usr/bin/clang"),
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                str(lz4_source),
                str(adapter_source),
            ]
            if sys.platform == "darwin":
                command.extend(["-dynamiclib", "-o", str(library)])
            else:
                command.extend(["-shared", "-fPIC", "-o", str(library)])
            subprocess.run(command, check=True, capture_output=True, text=True)
            loaded = ctypes.CDLL(str(library))

            byte_pointer = ctypes.POINTER(ctypes.c_ubyte)
            decoder = loaded.open_cfw_lz4_decompress_safe_legacy
            decoder.argtypes = [
                byte_pointer,
                byte_pointer,
                ctypes.c_int,
                ctypes.c_int,
            ]
            decoder.restype = ctypes.c_int
            adapter = loaded.open_cfw_evenhub_mode2_decompress_legacy
            adapter.argtypes = [
                byte_pointer,
                ctypes.c_uint,
                byte_pointer,
                ctypes.c_uint,
            ]
            adapter.restype = ctypes.c_uint

            def literal_block(payload: bytes) -> bytes:
                length = len(payload)
                token_length = min(length, 15)
                encoded = bytearray([token_length << 4])
                if length >= 15:
                    extension = length - 15
                    while extension >= 255:
                        encoded.append(255)
                        extension -= 255
                    encoded.append(extension)
                encoded.extend(payload)
                return bytes(encoded)

            def execute(
                function: ctypes._CFuncPtr,
                encoded: bytes,
                capacity: int,
            ) -> tuple[int, bytes, bytes]:
                input_array = (ctypes.c_ubyte * max(1, len(encoded)))(
                    *(encoded or b"\0")
                )
                output_array = (ctypes.c_ubyte * max(1, capacity + 8))(
                    *([0xCC] * max(1, capacity + 8))
                )
                if function is adapter:
                    result = int(
                        function(
                            input_array,
                            len(encoded),
                            output_array,
                            capacity,
                        )
                    )
                else:
                    result = int(
                        function(
                            input_array,
                            output_array,
                            len(encoded),
                            capacity,
                        )
                    )
                return (
                    result,
                    bytes(output_array[:max(0, result)]),
                    bytes(output_array[capacity:capacity + 8]),
                )

            cases = [
                (b"\x00", b""),
                (literal_block(b"hello world"), b"hello world"),
                (literal_block(bytes(range(256)) + b"tail"), bytes(range(256)) + b"tail"),
                (
                    b"\x51hello\x05\x00\x50world",
                    b"hellohelloworld",
                ),
                (
                    b"\x1fA\x01\x00\x14\x50tail!",
                    b"A" * 40 + b"tail!",
                ),
            ]
            for encoded, expected in cases:
                for function in (decoder, adapter):
                    with self.subTest(
                        function=function.__name__,
                        encoded=encoded.hex(),
                    ):
                        result, output, guard = execute(
                            function,
                            encoded,
                            len(expected),
                        )
                        self.assertEqual(result, len(expected))
                        self.assertEqual(output, expected)
                        self.assertEqual(guard, b"\xCC" * len(guard))

                if expected:
                    direct_result, _output, direct_guard = execute(
                        decoder,
                        encoded,
                        len(expected) - 1,
                    )
                    adapter_result, _output, adapter_guard = execute(
                        adapter,
                        encoded,
                        len(expected) - 1,
                    )
                    self.assertLess(direct_result, 0)
                    self.assertEqual(adapter_result, 0)
                    self.assertEqual(
                        direct_guard,
                        b"\xCC" * len(direct_guard),
                    )
                    self.assertEqual(
                        adapter_guard,
                        b"\xCC" * len(adapter_guard),
                    )

            malformed = [
                b"",
                b"\x10",
                b"\x50A",
                b"\xF0",
                b"\x10A\x01\x00",
                b"\x10A\x02\x00\x50tail!",
                b"\x10A\x00\x00\x50tail!",
                b"\x1fA\x01\x00\xff\x00\x00\x00\x00\x00\x00\x00",
            ]
            for encoded in malformed:
                direct_result, _output, direct_guard = execute(
                    decoder,
                    encoded,
                    96,
                )
                adapter_result, _output, adapter_guard = execute(
                    adapter,
                    encoded,
                    96,
                )
                with self.subTest(malformed=encoded.hex()):
                    self.assertLess(direct_result, 0)
                    self.assertEqual(adapter_result, 0)
                    self.assertEqual(
                        direct_guard,
                        b"\xCC" * len(direct_guard),
                    )
                    self.assertEqual(
                        adapter_guard,
                        b"\xCC" * len(adapter_guard),
                    )

            one_byte = (ctypes.c_ubyte * 1)(0)
            output = (ctypes.c_ubyte * 8)(*[0xCC] * 8)
            self.assertLess(decoder(None, output, 1, 8), 0)
            self.assertLess(decoder(one_byte, None, 1, 8), 0)
            self.assertEqual(adapter(None, 1, output, 8), 0)
            self.assertEqual(adapter(one_byte, 1, None, 8), 0)

